// ─── LOG DAILY (บันทึกตาย/คัด ประจำวัน) ────────────────────
function LogDailyPage({lang="th",daily, setDaily, onBack}) {
  const [sel, setSel] = useState(0);
  const h = daily[sel];

  const upd = (field, val) => {
    setDaily(prev => prev.map((x,i) => i===sel ? {...x, [field]: Math.max(0, Number(val)||0)} : x));
  };

  return (
    <div>
      <BackBtn onClick={onBack}/>
      <SectionTitle icon="📋" title={t("dailyLog",lang)} color={C.green}/>

      {/* House selector */}
      <div style={{display:"flex",gap:6,marginBottom:16,overflowX:"auto",paddingBottom:4}}>
        {daily.map((d,i)=>(
          <button key={i} onClick={()=>setSel(i)} style={{
            flexShrink:0, padding:"7px 12px", borderRadius:10, border:"1.5px solid",
            fontSize:12, fontWeight:600, cursor:"pointer",
            borderColor: sel===i ? C.green : C.greenMid,
            background: sel===i ? C.green : C.white,
            color: sel===i ? C.white : C.textMid,
          }}>{d.house.replace(" (สระบุรี)","").replace(" (ลพบุรี)","")}</button>
        ))}
      </div>

      <Card>
        <div style={{fontWeight:700,fontSize:15,color:C.text,marginBottom:16}}>{h.house}</div>

        {/* Dead AM/PM */}
        <div style={{background:C.redPale,borderRadius:14,padding:"14px",marginBottom:12}}>
          <div style={{fontWeight:700,fontSize:13,color:C.red,marginBottom:10}}>💀 จำนวนตาย</div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
            <div>
              <label style={{...LS,color:C.red}}>☀️ เช้า (ตัว)</label>
              <input type="number" value={h.deadAM} onChange={e=>upd("deadAM",e.target.value)}
                style={{...IS,borderColor:C.red+"44",background:"#fff",textAlign:"center",fontSize:18,fontWeight:700}}/>
            </div>
            <div>
              <label style={{...LS,color:C.red}}>🌙 เย็น (ตัว)</label>
              <input type="number" value={h.deadPM} onChange={e=>upd("deadPM",e.target.value)}
                style={{...IS,borderColor:C.red+"44",background:"#fff",textAlign:"center",fontSize:18,fontWeight:700}}/>
            </div>
          </div>
          <div style={{textAlign:"center",marginTop:8,fontSize:12,color:C.red}}>
            รวมตาย = <strong>{h.deadAM+h.deadPM} ตัว</strong>
          </div>
        </div>

        {/* Cull AM/PM */}
        <div style={{background:C.orangePale,borderRadius:14,padding:"14px",marginBottom:16}}>
          <div style={{fontWeight:700,fontSize:13,color:C.orange,marginBottom:10}}>✂️ จำนวนคัด</div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
            <div>
              <label style={{...LS,color:C.orange}}>☀️ เช้า (ตัว)</label>
              <input type="number" value={h.cullAM} onChange={e=>upd("cullAM",e.target.value)}
                style={{...IS,borderColor:C.orange+"44",background:"#fff",textAlign:"center",fontSize:18,fontWeight:700}}/>
            </div>
            <div>
              <label style={{...LS,color:C.orange}}>🌙 เย็น (ตัว)</label>
              <input type="number" value={h.cullPM} onChange={e=>upd("cullPM",e.target.value)}
                style={{...IS,borderColor:C.orange+"44",background:"#fff",textAlign:"center",fontSize:18,fontWeight:700}}/>
            </div>
          </div>
          <div style={{textAlign:"center",marginTop:8,fontSize:12,color:C.orange}}>
            รวมคัด = <strong>{h.cullAM+h.cullPM} ตัว</strong>
          </div>
        </div>

        {/* Summary */}
        <div style={{background:C.grayPale,borderRadius:12,padding:"12px 14px",marginBottom:16,display:"flex",justifyContent:"space-between"}}>
          <span style={{fontSize:14,color:C.textMid}}>ตายรวม + คัดรวม</span>
          <span style={{fontWeight:700,fontSize:16,color:C.red}}>
            {h.deadAM+h.deadPM+h.cullAM+h.cullPM} ตัว
          </span>
        </div>

        {/* กระดานไก่ */}
        <div style={{marginBottom:16}}>
          <label style={LS}>📋 อัพโหลดรูปกระดานไก่</label>
          {h.boardImg && (
            <img src={h.boardImg} style={{width:"100%",borderRadius:12,marginBottom:8,maxHeight:160,objectFit:"cover"}} alt="กระดาน"/>
          )}
          <label style={{display:"block",background:C.sand||"#F2EDD5",border:`1.5px dashed ${C.textLight}`,borderRadius:12,padding:"14px",textAlign:"center",cursor:"pointer"}}>
            <input type="file" accept="image/*" capture="environment" style={{display:"none"}}
              onChange={e=>{
                const file=e.target.files[0]; if(!file) return;
                const url=URL.createObjectURL(file);
                setDaily(prev=>prev.map((x,i)=>i===sel?{...x,boardImg:url}:x));
              }}/>
            <div style={{fontSize:18}}>{h.boardImg ? "🔄 เปลี่ยนรูป" : "📷 ถ่ายหรืออัพโหลด"}</div>
          </label>
        </div>

        <button onClick={onBack} style={{width:"100%",padding:"13px",borderRadius:14,border:"none",background:C.green,color:C.white,fontSize:15,fontWeight:700,cursor:"pointer"}}>
          ✓ บันทึกแล้ว
        </button>
      </Card>
    </div>
  );
}

