// ─── ADD/EDIT FORM MODAL ──────────────────────────────────────
function StaffForm({initial, onSave, onClose}) {
  const empty = {name:"",photo:null,farm:FARMS[0],house:"เล้า 1",zone:ZONES[0],
    duty:{th:"",lo:"",km:"",en:""}};
  const [form, setForm] = useState(initial || empty);
  const [langTab, setLangTab] = useState("th");
  const isEdit = !!initial;

  const setDuty = (lang, val) => setForm(f=>({...f,duty:{...f.duty,[lang]:val}}));

  return (
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.55)",zIndex:300,display:"flex",alignItems:"flex-end"}}
         onClick={onClose}>
      <div style={{background:C.white,borderRadius:"22px 22px 0 0",width:"100%",maxWidth:480,
                   margin:"0 auto",padding:"22px 18px 36px",maxHeight:"90vh",overflowY:"auto"}}
           onClick={e=>e.stopPropagation()}>

        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18}}>
          <div style={{fontWeight:700,fontSize:17,color:C.ink}}>{isEdit?"✏️ แก้ไขข้อมูล":"➕ เพิ่มพนักงาน"}</div>
          <button onClick={onClose} style={{background:C.grayPale,border:"none",borderRadius:"50%",width:32,height:32,fontSize:16,cursor:"pointer"}}>×</button>
        </div>

        {/* รูปพนักงาน */}
        <div style={{textAlign:"center",marginBottom:16}}>
          <div style={{position:"relative",display:"inline-block"}}>
            <Avatar photo={form.photo} size={72} fontSize={30}/>
            <label style={{
              position:"absolute",bottom:-2,right:-2,background:C.green,
              borderRadius:"50%",width:24,height:24,display:"flex",
              alignItems:"center",justifyContent:"center",cursor:"pointer",
              border:"2px solid #fff",fontSize:13
            }}>
              <input type="file" accept="image/*" capture="environment" style={{display:"none"}}
                onChange={e=>{
                  const f=e.target.files[0]; if(!f) return;
                  setForm(prev=>({...prev,photo:URL.createObjectURL(f)}));
                }}/>
              📷
            </label>
          </div>
          <div style={{fontSize:11,color:C.inkLight,marginTop:6}}>แตะ 📷 เพื่ออัพโหลดรูป</div>
        </div>

        {/* ชื่อ */}
        <label style={LS}>ชื่อ-นามสกุล</label>
        <input value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))}
          placeholder="เช่น สมชาย ใจดี" style={{...IS,marginBottom:12}}/>

        {/* ฟาร์ม */}
        <label style={LS}>ฟาร์ม</label>
        <select value={form.farm}
          onChange={e=>setForm(f=>({...f,farm:e.target.value,house:HOUSES[e.target.value][0]}))}
          style={{...IS,marginBottom:12}}>
          {FARMS.map(f=><option key={f}>{f}</option>)}
        </select>

        {/* เล้า */}
        <label style={LS}>สังกัดเล้า</label>
        <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:6,marginBottom:12}}>
          {HOUSES[form.farm].map(h=>(
            <button key={h} onClick={()=>setForm(f=>({...f,house:h}))} style={{
              padding:"7px 4px",borderRadius:10,border:"1.5px solid",fontSize:12,fontWeight:600,cursor:"pointer",
              borderColor:form.house===h?C.green:C.greenMid,
              background:form.house===h?C.green:C.white,
              color:form.house===h?C.white:C.inkMid
            }}>{h}</button>
          ))}
        </div>

        {/* โซนเวร */}
        <label style={LS}>พื้นที่เวร</label>
        <select value={form.zone} onChange={e=>setForm(f=>({...f,zone:e.target.value}))}
          style={{...IS,marginBottom:12}}>
          {ZONES.map(z=><option key={z}>{z}</option>)}
        </select>

        {/* หน้าที่ 4 ภาษา */}
        <label style={LS}>หน้าที่ประจำพื้นที่</label>
        <div style={{display:"flex",gap:6,marginBottom:8}}>
          {LANGS.map(l=>(
            <button key={l.key} onClick={()=>setLangTab(l.key)} style={{
              flex:1,padding:"6px 2px",borderRadius:8,border:"1.5px solid",fontSize:13,cursor:"pointer",
              borderColor:langTab===l.key?C.green:C.greenMid,
              background:langTab===l.key?C.green:C.white,
              color:langTab===l.key?C.white:C.inkMid
            }}>{l.label}</button>
          ))}
        </div>
        <textarea value={form.duty[langTab]}
          onChange={e=>setDuty(langTab,e.target.value)}
          placeholder={`กรอกหน้าที่ภาษา ${LANGS.find(l=>l.key===langTab)?.label}...`}
          style={{...IS,height:72,resize:"none",marginBottom:18}}/>

        {/* Actions */}
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
          <button onClick={onClose} style={{padding:"12px",borderRadius:12,border:`1.5px solid ${C.greenMid}`,background:C.white,color:C.inkMid,fontSize:14,cursor:"pointer"}}>{t("cancel",lang)}</button>
          <button onClick={()=>{if(!form.name.trim()) return; onSave(form);}}
            style={{padding:"12px",borderRadius:12,border:"none",background:C.green,color:C.white,fontSize:14,fontWeight:700,cursor:"pointer"}}>
            {isEdit?"บันทึกการแก้ไข":"เพิ่มพนักงาน ✓"}
          </button>
        </div>
      </div>
    </div>
  );
}

