// ─── STAFF PICKER ──────────────────────────────────────────────
function StaffPicker({label, value, onChange}) {
  const [open, setOpen]     = useState(false);
  const [custom, setCustom] = useState("");
  const isCustom = value && !STAFF_LIST.find(s=>s.label===value);

  const pick = (v) => { onChange(v); setOpen(false); };

  return (
    <div style={{position:"relative",marginBottom:10}}>
      <label style={LS}>{label}</label>
      <button type="button" onClick={()=>setOpen(!open)} style={{
        width:"100%",padding:"10px 12px",borderRadius:10,
        border:`1.5px solid ${open?C.green:C.greenMid}`,
        background:C.white,textAlign:"left",fontSize:14,color:value?C.ink:C.textLight,
        cursor:"pointer",display:"flex",justifyContent:"space-between",alignItems:"center",
        boxSizing:"border-box",fontFamily:"inherit",
      }}>
        <span>{value||"เลือก..."}</span>
        <span style={{fontSize:12,color:C.textLight}}>{open?"▲":"▼"}</span>
      </button>

      {open && (
        <div style={{
          position:"absolute",top:"100%",left:0,right:0,zIndex:200,
          background:C.white,borderRadius:12,boxShadow:"0 8px 24px rgba(0,0,0,0.15)",
          border:`1.5px solid ${C.greenMid}`,marginTop:4,maxHeight:300,overflowY:"auto"
        }}>
          {ROLE_GROUPS.map(role => {
            const members = STAFF_LIST.filter(s=>s.role===role);
            return (
              <div key={role}>
                <div style={{padding:"6px 12px 3px",fontSize:10,fontWeight:700,color:C.textLight,background:C.offwhite,letterSpacing:"0.05em"}}>
                  {role.toUpperCase()}
                </div>
                {members.map(s=>(
                  <button key={s.label} type="button" onClick={()=>pick(s.label)} style={{
                    width:"100%",padding:"9px 16px",border:"none",background:value===s.label?C.greenPale:C.white,
                    textAlign:"left",fontSize:13,color:value===s.label?C.green:C.ink,
                    fontWeight:value===s.label?700:400,cursor:"pointer",display:"block",fontFamily:"inherit"
                  }}>{s.label}</button>
                ))}
              </div>
            );
          })}
          {/* อื่นๆ — กรอกเอง */}
          <div>
            <div style={{padding:"6px 12px 3px",fontSize:10,fontWeight:700,color:C.textLight,background:C.offwhite,letterSpacing:"0.05em"}}>
              อื่นๆ
            </div>
            <div style={{padding:"8px 12px",display:"flex",gap:6}}>
              <input value={custom} onChange={e=>setCustom(e.target.value)}
                placeholder="ระบุชื่อ..." style={{...IS,flex:1,padding:"7px 10px",fontSize:13}}
                onClick={e=>e.stopPropagation()}/>
              <button type="button" onClick={()=>{if(custom.trim())pick(custom.trim());}} style={{
                padding:"7px 12px",borderRadius:8,border:"none",background:C.green,color:C.white,
                fontSize:12,fontWeight:700,cursor:"pointer"
              }}>✓</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}


// ─── FINANCE PAGE ──────────────────────────────────────────────
function FinancePage({expenses, setExpenses, lang="th"}) {
  const [tab, setTab]         = useState("dashboard"); // dashboard|list|add
  const [branch, setBranch]   = useState("ทั้งหมด");
  const [period, setPeriod]   = useState("week");      // week|month
  const [filterGroup, setFilterGroup] = useState("ทั้งหมด");
  const [filterType, setFilterType]   = useState("ทั้งหมด");
  const [filterPerson, setFilterPerson] = useState("ทั้งหมด");
  const [editId, setEditId]   = useState(null);
  const [confirmDel, setConfirmDel] = useState(null);

  const emptyForm = {
    date:today(), branch:BRANCHES[0], group:"น้ำมัน",
    type:FUEL_TYPES[0], desc:"", amount:"",
    source:"", sourceType:"ร้าน", orderedBy:"", paidBy:"",
    paidFrom:"กองทุน JK1", payMethod:"เงินสด", imgs:[],
  };
  const [form, setForm] = useState(emptyForm);
  const [showAdd, setShowAdd] = useState(false);
  const [formErr, setFormErr] = useState("");

  // filter by branch
  const filtered = expenses.filter(e=>{
    if(branch!=="ทั้งหมด" && e.branch!==branch) return false;
    if(filterGroup!=="ทั้งหมด" && e.group!==filterGroup) return false;
    if(filterType!=="ทั้งหมด" && e.type!==filterType) return false;
    if(filterPerson!=="ทั้งหมด" && e.orderedBy!==filterPerson) return false;
    return true;
  });
  const allPeople = [...new Set(expenses.map(e=>e.orderedBy).filter(Boolean))];
  const typeOptions = filterGroup==="ทั้งหมด" ? [] : (EXPENSE_CATS.find(c=>c.group===filterGroup)?.items||[]);

  // today
  const todayStr = today();
  const todayExp = expenses.filter(e=>e.date===todayStr);
  const todayTotal = todayExp.reduce((s,e)=>s+e.amount,0);

  // week / month totals
  const now = new Date();
  const weekAgo  = new Date(now); weekAgo.setDate(now.getDate()-6);
  const monthAgo = new Date(now); monthAgo.setDate(now.getDate()-29);
  const inPeriod = (d) => new Date(d) >= (period==="week"?weekAgo:monthAgo);
  const periodExp = filtered.filter(e=>inPeriod(e.date));

  // group totals for chart
  const groupTotals = EXPENSE_CATS.map(c=>{
    const total = periodExp.filter(e=>e.group===c.group).reduce((s,e)=>s+e.amount,0);
    return {group:c.group, total};
  }).filter(g=>g.total>0);
  const maxG = Math.max(...groupTotals.map(g=>g.total),1);

  // daily chart data (last 7 or 30 days)
  const days = period==="week" ? 7 : 30;
  const dailyData = Array.from({length:days},(_, i)=>{
    const d = new Date(now); d.setDate(now.getDate()-(days-1-i));
    const ds = d.toISOString().slice(0,10);
    const total = filtered.filter(e=>e.date===ds).reduce((s,e)=>s+e.amount,0);
    return {ds, label: period==="week"?["อา","จ","อ","พ","พฤ","ศ","ส"][d.getDay()]:String(d.getDate()), total};
  });
  const maxDay = Math.max(...dailyData.map(d=>d.total),1);

  const saveExpense = () => {
    const amt = parseFloat(String(form.amount).replace(/,/g,""));
    if(!form.desc) { setFormErr("กรุณากรอกรายละเอียด"); return; }
    if(!form.amount || isNaN(amt) || amt <= 0) { setFormErr("กรุณากรอกจำนวนเงิน"); return; }
    setFormErr("");
    if(editId) {
      setExpenses(prev=>prev.map(e=>e.id===editId?{...form,id:editId,amount:amt}:e));
      setEditId(null);
    } else {
      setExpenses(prev=>[{...form,id:Date.now(),amount:amt},...prev]);
    }
    setForm(emptyForm);
    setShowAdd(false);
    setTab("dashboard");
  };

  const startEdit = (e2) => {
    setForm({...e2,amount:String(e2.amount)});
    setEditId(e2.id); setShowAdd(true); setTab("add");
  };

  const groupColor = {"น้ำมัน":C.orange,"ซ่อมบำรุง":C.blue,"อื่นๆ":C.purple};
  const groupPale  = {"น้ำมัน":C.orangePale,"ซ่อมบำรุง":C.bluePale,"อื่นๆ":C.purplePale};

  // ── ADD FORM ──
  if(tab==="add") return (
    <div>
      <BackBtn onClick={()=>{setTab("dashboard");setEditId(null);setForm(emptyForm);setFormErr("");}}/>
      <SectionTitle icon="💰" title={editId?"แก้ไขรายจ่าย":"เบิกค่าใช้จ่าย"} color={C.blue}/>
      <Card>
        {/* วันที่ + สาขา */}
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:10}}>
          <div>
            <label style={LS}>วันที่</label>
            <input type="date" value={form.date} onChange={e=>setForm({...form,date:e.target.value})} style={IS}/>
          </div>
          <div>
            <label style={LS}>สาขา</label>
            <select value={form.branch} onChange={e=>setForm({...form,branch:e.target.value,paidFrom:"กองทุน "+(e.target.value.split(" - ")[0]||e.target.value)})} style={IS}>
              {BRANCHES.map(b=><option key={b}>{b}</option>)}
            </select>
          </div>
        </div>

        {/* หมวดหลัก */}
        <label style={LS}>หมวดหลัก</label>
        <div style={{display:"flex",gap:6,marginBottom:10}}>
          {EXPENSE_CATS.map(c=>(
            <button key={c.group} onClick={()=>setForm({...form,group:c.group,type:c.items[0]})} style={{
              flex:1,padding:"8px 4px",borderRadius:10,border:"1.5px solid",fontSize:12,fontWeight:600,cursor:"pointer",
              borderColor:form.group===c.group?(groupColor[c.group]||C.green):C.greenMid,
              background:form.group===c.group?(groupPale[c.group]||C.greenPale):C.white,
              color:form.group===c.group?(groupColor[c.group]||C.green):C.textMid,
            }}>{c.group}</button>
          ))}
        </div>

        {/* ประเภทย่อย */}
        <label style={LS}>ประเภท</label>
        <select value={form.type} onChange={e=>setForm({...form,type:e.target.value})} style={{...IS,marginBottom:10}}>
          {(EXPENSE_CATS.find(c=>c.group===form.group)?.items||[]).map(t=><option key={t}>{t}</option>)}
        </select>

        {/* รายละเอียด */}
        <label style={LS}>รายละเอียด</label>
        <input value={form.desc} onChange={e=>setForm({...form,desc:e.target.value})}
          placeholder="เช่น เติมน้ำมันรถกระบะ" style={{...IS,marginBottom:10}}/>

        {/* จำนวนเงิน */}
        <label style={LS}>จำนวนเงิน (฿)</label>
        <input type="number" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})}
          placeholder="0" style={{...IS,textAlign:"center",fontSize:20,fontWeight:700,marginBottom:10}}/>

        {/* แหล่งซื้อ */}
        <label style={LS}>แหล่งซื้อ</label>
        <div style={{display:"flex",gap:6,marginBottom:6}}>
          {["ร้าน","ออนไลน์","อื่นๆ"].map(t=>(
            <button key={t} onClick={()=>setForm({...form,sourceType:t})} style={{
              flex:1,padding:"6px",borderRadius:8,border:"1.5px solid",fontSize:12,fontWeight:600,cursor:"pointer",
              borderColor:form.sourceType===t?C.teal:C.greenMid,
              background:form.sourceType===t?C.tealPale:C.white,
              color:form.sourceType===t?C.teal:C.textMid,
            }}>{t}</button>
          ))}
        </div>
        <input value={form.source} onChange={e=>setForm({...form,source:e.target.value})}
          placeholder={form.sourceType==="ออนไลน์"?"เช่น Shopee, Lazada":"เช่น ร้านวัสดุทวี"} style={{...IS,marginBottom:10}}/>

        {/* ผู้เบิก + ผู้จ่าย */}
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
          <StaffPicker label="ผู้เบิกของ" value={form.orderedBy} onChange={v=>setForm({...form,orderedBy:v})}/>
          <StaffPicker label="ผู้จ่ายเงิน" value={form.paidBy} onChange={v=>setForm({...form,paidBy:v})}/>
        </div>

        {/* เงินจากไหน + วิธีชำระ */}
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:10}}>
          <div>
            <label style={LS}>เงินจาก</label>
            <input value={form.paidFrom} onChange={e=>setForm({...form,paidFrom:e.target.value})}
              placeholder="เช่น กองทุนลพบุรี" style={IS}/>
          </div>
          <div>
            <label style={LS}>รูปแบบชำระ</label>
            <select value={form.payMethod} onChange={e=>setForm({...form,payMethod:e.target.value})} style={IS}>
              {PAY_METHODS.map(p=><option key={p}>{p}</option>)}
            </select>
          </div>
        </div>

        {/* อัพโหลดสลิป/รูป */}
        <label style={LS}>อัพโหลดสลิป / ใบเสร็จ</label>
        <label style={{display:"block",background:"#F2EDD5",border:`1.5px dashed ${C.textLight}`,borderRadius:12,padding:"14px",textAlign:"center",cursor:"pointer",marginBottom:form.imgs.length>0?8:16}}>
          <input type="file" accept="image/*" multiple style={{display:"none"}}
            onChange={e=>{
              const urls=Array.from(e.target.files).slice(0,5).map(f=>URL.createObjectURL(f));
              setForm(prev=>({...prev,imgs:[...prev.imgs,...urls].slice(0,5)}));
            }}/>
          <div style={{fontSize:22,marginBottom:3}}>📎</div>
          <div style={{fontSize:13,color:C.textLight}}>แนบสลิป / ใบเสร็จ</div>
        </label>
        {form.imgs.length>0&&(
          <div style={{display:"flex",gap:6,marginBottom:14,overflowX:"auto"}}>
            {form.imgs.map((url,i)=>(
              <div key={i} style={{position:"relative",flexShrink:0}}>
                <img src={url} style={{width:60,height:60,objectFit:"cover",borderRadius:8,border:`1.5px solid ${C.greenMid}`}} alt=""/>
                <button onClick={()=>setForm(prev=>({...prev,imgs:prev.imgs.filter((_,j)=>j!==i)}))}
                  style={{position:"absolute",top:-4,right:-4,background:C.red,color:"#fff",border:"none",borderRadius:"50%",width:16,height:16,fontSize:9,cursor:"pointer"}}>×</button>
              </div>
            ))}
          </div>
        )}

        {formErr&&<div style={{background:C.redPale,border:`1px solid ${C.red}44`,borderRadius:10,padding:"8px 12px",marginBottom:10,fontSize:13,color:C.red}}>⚠️ {formErr}</div>}
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
          <button onClick={()=>{setTab("dashboard");setEditId(null);setForm(emptyForm);setFormErr("");}} style={{padding:"12px",borderRadius:12,border:`1.5px solid ${C.greenMid}`,background:C.white,color:C.textMid,fontSize:14,cursor:"pointer"}}>{t("cancel",lang)}</button>
          <button onClick={saveExpense} style={{padding:"12px",borderRadius:12,border:"none",background:C.blue,color:C.white,fontSize:14,fontWeight:700,cursor:"pointer"}}>{editId?"บันทึกการแก้ไข ✓":"บันทึก ✓"}</button>
        </div>
      </Card>
    </div>
  );

  // ── LIST ──
  if(tab==="list") {
    const listExp = filtered.slice().sort((a,b)=>b.date.localeCompare(a.date));
    return (
      <div>
        <BackBtn onClick={()=>setTab("dashboard")}/>
        <SectionTitle icon="📋" title="รายการทั้งหมด" color={C.blue}/>
        <div style={{display:"flex",gap:6,marginBottom:12}}>
          {["ทั้งหมด",...BRANCHES].map(b=>(
            <button key={b} onClick={()=>setBranch(b)} style={{
              flex:1,padding:"7px",borderRadius:10,border:"1.5px solid",fontSize:12,fontWeight:600,cursor:"pointer",
              borderColor:branch===b?C.blue:C.greenMid,background:branch===b?C.blue:C.white,color:branch===b?C.white:C.textMid,
            }}>{b}</button>
          ))}
        </div>
        {listExp.map(e=>{
          const gc=groupColor[e.group]||C.gray; const gp=groupPale[e.group]||C.grayPale;
          return (
            <div key={e.id} style={{background:C.white,borderRadius:14,marginBottom:10,border:`1.5px solid ${gc}33`,overflow:"hidden",display:"flex"}}>
              {/* thumb */}
              <div style={{width:70,flexShrink:0,background:gp,display:"flex",alignItems:"center",justifyContent:"center",fontSize:26,position:"relative"}}>
                {e.imgs.length>0?<img src={e.imgs[0]} style={{width:"100%",height:"100%",objectFit:"cover"}} alt=""/>:
                  <span>{e.group==="น้ำมัน"?"⛽":e.group==="ซ่อมบำรุง"?"🔧":"💳"}</span>}
                {e.imgs.length>1&&<div style={{position:"absolute",bottom:3,right:3,background:"rgba(0,0,0,0.55)",color:"#fff",borderRadius:5,padding:"1px 4px",fontSize:9}}>+{e.imgs.length-1}</div>}
              </div>
              <div style={{flex:1,padding:"10px 12px",minWidth:0}}>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:3}}>
                  <div>
                    <span style={{background:gp,color:gc,borderRadius:8,padding:"1px 8px",fontSize:10,fontWeight:600}}>{e.type.length>12?e.type.slice(0,12)+"…":e.type}</span>
                    <span style={{fontSize:10,color:C.textLight,marginLeft:6}}>{e.branch}</span>
                  </div>
                  <span style={{fontWeight:700,color:gc,fontSize:14}}>฿{fmt(e.amount)}</span>
                </div>
                <div style={{fontSize:13,color:C.text,marginBottom:2}}>{e.desc}</div>
                <div style={{fontSize:11,color:C.textLight}}>📅{e.date} · 👤{e.orderedBy} · 💳{e.payMethod}</div>
                {/* edit/delete */}
                {confirmDel===e.id?(
                  <div style={{marginTop:6,display:"flex",gap:6,alignItems:"center"}}>
                    <span style={{fontSize:11,color:C.red,flex:1}}>ลบรายการนี้?</span>
                    <button onClick={()=>setConfirmDel(null)} style={{padding:"3px 10px",borderRadius:7,border:`1px solid ${C.greenMid}`,background:C.white,color:C.textMid,fontSize:11,cursor:"pointer"}}>{t("cancel",lang)}</button>
                    <button onClick={()=>{setExpenses(prev=>prev.filter(x=>x.id!==e.id));setConfirmDel(null);}} style={{padding:"3px 10px",borderRadius:7,border:"none",background:C.red,color:C.white,fontSize:11,fontWeight:700,cursor:"pointer"}}>ลบ</button>
                  </div>
                ):(
                  <div style={{display:"flex",gap:6,marginTop:6}}>
                    <button onClick={()=>startEdit(e)} style={{padding:"4px 12px",borderRadius:7,border:`1px solid ${C.blue}`,background:C.bluePale,color:C.blue,fontSize:11,fontWeight:600,cursor:"pointer"}}>✏️ แก้ไข</button>
                    <button onClick={()=>setConfirmDel(e.id)} style={{padding:"4px 12px",borderRadius:7,border:`1px solid ${C.red}`,background:C.redPale,color:C.red,fontSize:11,fontWeight:600,cursor:"pointer"}}>🗑️ ลบ</button>
                  </div>
                )}
              </div>
            </div>
          );
        })}
        {listExp.length===0&&<div style={{textAlign:"center",color:C.textLight,padding:32}}>ยังไม่มีรายการ</div>}
      </div>
    );
  }

  // ── DASHBOARD ──
  const periodTotal = periodExp.reduce((s,e)=>s+e.amount,0);
  const branchTotals = BRANCHES.map(b=>({branch:b,total:filtered.filter(e=>e.branch===b&&inPeriod(e.date)).reduce((s,e)=>s+e.amount,0)}));
  const maxBranch = Math.max(...branchTotals.map(b=>b.total),1);

  return (
    <div>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
        <SectionTitle icon="💰" title={t("finance",lang)} color={C.blue}/>
        <button onClick={()=>{setEditId(null);setForm(emptyForm);setTab("add");}} style={{padding:"7px 14px",borderRadius:10,border:"none",background:C.blue,color:C.white,fontSize:13,fontWeight:700,cursor:"pointer"}}>+ เบิกจ่าย</button>
      </div>

      {/* ─── FILTER PANEL ─── */}
      <Card style={{background:C.bluePale,border:`1px solid ${C.blue}22`,padding:"14px"}}>
        <div style={{fontWeight:700,fontSize:13,color:C.blue,marginBottom:10}}>🔍 ตัวกรอง</div>

        {/* สาขา */}
        <div style={{marginBottom:8}}>
          <div style={{fontSize:11,color:C.textMid,fontWeight:600,marginBottom:4}}>สาขา</div>
          <div style={{display:"flex",gap:5,flexWrap:"wrap"}}>
            {["ทั้งหมด",...BRANCHES].map(b=>(
              <button key={b} onClick={()=>setBranch(b)} style={{
                padding:"5px 10px",borderRadius:8,border:"1.5px solid",fontSize:11,fontWeight:600,cursor:"pointer",
                borderColor:branch===b?C.blue:C.greenMid,background:branch===b?C.blue:C.white,color:branch===b?C.white:C.textMid,
              }}>{b==="ทั้งหมด"?"ทั้งหมด":b.split(" - ")[0]}</button>
            ))}
          </div>
        </div>

        {/* หมวดหมู่ */}
        <div style={{marginBottom:8}}>
          <div style={{fontSize:11,color:C.textMid,fontWeight:600,marginBottom:4}}>หมวดหมู่</div>
          <div style={{display:"flex",gap:5,flexWrap:"wrap"}}>
            {["ทั้งหมด",...EXPENSE_CATS.map(c=>c.group)].map(g=>(
              <button key={g} onClick={()=>{setFilterGroup(g);setFilterType("ทั้งหมด");}} style={{
                padding:"5px 10px",borderRadius:8,border:"1.5px solid",fontSize:11,fontWeight:600,cursor:"pointer",
                borderColor:filterGroup===g?C.orange:C.greenMid,background:filterGroup===g?C.orange:C.white,color:filterGroup===g?C.white:C.textMid,
              }}>{g}</button>
            ))}
          </div>
        </div>

        {/* ประเภทย่อย (แสดงเฉพาะเมื่อเลือกหมวด) */}
        {filterGroup!=="ทั้งหมด" && typeOptions.length>0 && (
          <div style={{marginBottom:8}}>
            <div style={{fontSize:11,color:C.textMid,fontWeight:600,marginBottom:4}}>ประเภทย่อย</div>
            <div style={{display:"flex",gap:5,flexWrap:"wrap"}}>
              {["ทั้งหมด",...typeOptions].map(t=>(
                <button key={t} onClick={()=>setFilterType(t)} style={{
                  padding:"4px 9px",borderRadius:7,border:"1.5px solid",fontSize:10,fontWeight:600,cursor:"pointer",
                  borderColor:filterType===t?C.teal:C.greenMid,background:filterType===t?C.teal:C.white,color:filterType===t?C.white:C.textMid,
                }}>{t.length>14?t.slice(0,14)+"…":t}</button>
              ))}
            </div>
          </div>
        )}

        {/* ผู้เบิก */}
        {allPeople.length>0 && (
          <div>
            <div style={{fontSize:11,color:C.textMid,fontWeight:600,marginBottom:4}}>ผู้เบิก</div>
            <div style={{display:"flex",gap:5,flexWrap:"wrap"}}>
              {["ทั้งหมด",...allPeople].map(p=>(
                <button key={p} onClick={()=>setFilterPerson(p)} style={{
                  padding:"4px 9px",borderRadius:7,border:"1.5px solid",fontSize:10,fontWeight:600,cursor:"pointer",
                  borderColor:filterPerson===p?C.purple:C.greenMid,background:filterPerson===p?C.purple:C.white,color:filterPerson===p?C.white:C.textMid,
                }}>{p}</button>
              ))}
            </div>
          </div>
        )}

        {/* Active filter summary + reset */}
        {(branch!=="ทั้งหมด"||filterGroup!=="ทั้งหมด"||filterType!=="ทั้งหมด"||filterPerson!=="ทั้งหมด") && (
          <div style={{marginTop:10,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
            <div style={{fontSize:11,color:C.blue}}>
              กรอง: {[branch!=="ทั้งหมด"&&branch,filterGroup!=="ทั้งหมด"&&filterGroup,filterType!=="ทั้งหมด"&&filterType,filterPerson!=="ทั้งหมด"&&("👤"+filterPerson)].filter(Boolean).join(" · ")}
            </div>
            <button onClick={()=>{setBranch("ทั้งหมด");setFilterGroup("ทั้งหมด");setFilterType("ทั้งหมด");setFilterPerson("ทั้งหมด");}} style={{padding:"4px 10px",borderRadius:7,border:"none",background:C.red,color:C.white,fontSize:11,fontWeight:600,cursor:"pointer"}}>
              ล้าง ×
            </button>
          </div>
        )}
      </Card>

      {/* TODAY ANNOUNCEMENT */}
      <div style={{background:`linear-gradient(135deg,${C.blue},#1A5276)`,borderRadius:18,padding:"16px 18px",color:C.white,marginBottom:14}}>
        <div style={{fontSize:12,opacity:0.8,marginBottom:4}}>📢 วันนี้ {todayStr}</div>
        <div style={{fontSize:28,fontWeight:700,fontFamily:"serif",marginBottom:8}}>
          ฿{fmt(todayTotal)}
        </div>
        {todayExp.length===0
          ? <div style={{fontSize:13,opacity:0.75}}>ยังไม่มีรายการวันนี้</div>
          : todayExp.map((e,i)=>(
            <div key={i} style={{background:"rgba(255,255,255,0.12)",borderRadius:10,padding:"7px 10px",marginBottom:4,fontSize:12}}>
              <div style={{display:"flex",justifyContent:"space-between"}}>
                <span>🔸 {e.desc}</span>
                <span style={{fontWeight:700}}>฿{fmt(e.amount)}</span>
              </div>
              <div style={{opacity:0.75,marginTop:2}}>👤 เบิก: {e.orderedBy||"—"} · จ่าย: {e.paidBy||"—"} · จาก: {e.paidFrom||"—"}</div>
            </div>
          ))}
      </div>

      {/* Period toggle */}
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:14}}>
        {[["week","📅 สัปดาห์นี้"],["month","📆 เดือนนี้"]].map(([v,l])=>(
          <button key={v} onClick={()=>setPeriod(v)} style={{
            padding:"9px",borderRadius:10,border:"1.5px solid",fontSize:13,fontWeight:600,cursor:"pointer",
            borderColor:period===v?C.blue:C.greenMid,background:period===v?C.bluePale:C.white,color:period===v?C.blue:C.textMid,
          }}>{l}</button>
        ))}
      </div>

      {/* Summary cards */}
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:8,marginBottom:14}}>
        <div style={{background:C.bluePale,borderRadius:14,padding:"10px 6px",textAlign:"center"}}>
          <div style={{fontSize:10,color:C.textMid}}>รวม{period==="week"?"สัปดาห์":"เดือน"}</div>
          <div style={{fontWeight:700,fontSize:18,color:C.blue}}>฿{fmt(periodTotal)}</div>
        </div>
        <div style={{background:C.orangePale,borderRadius:14,padding:"10px 6px",textAlign:"center"}}>
          <div style={{fontSize:10,color:C.textMid}}>จำนวน</div>
          <div style={{fontWeight:700,fontSize:18,color:C.orange}}>{periodExp.length} ร.</div>
        </div>
        <div style={{background:C.purplePale,borderRadius:14,padding:"10px 6px",textAlign:"center"}}>
          <div style={{fontSize:10,color:C.textMid}}>ค่าเฉลี่ย/วัน</div>
          <div style={{fontWeight:700,fontSize:18,color:C.purple}}>฿{fmt(Math.round(periodTotal/(period==="week"?7:30)))}</div>
        </div>
      </div>

      {/* Daily bar chart */}
      <Card>
        <div style={{fontWeight:700,fontSize:14,color:C.text,marginBottom:12}}>📊 ค่าใช้จ่ายรายวัน ({period==="week"?"7":"30"} วัน)</div>
        <div style={{display:"flex",gap:period==="week"?8:3,alignItems:"flex-end",height:90}}>
          {dailyData.map((d,i)=>{
            const pct = Math.max(3,(d.total/maxDay)*100);
            const isToday = d.ds===todayStr;
            return (
              <div key={i} style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",gap:2}}>
                {d.total>0&&<div style={{fontSize:period==="week"?10:8,color:isToday?C.blue:C.textLight,fontWeight:isToday?700:400}}>{d.total>=1000?(d.total/1000).toFixed(1)+"k":d.total}</div>}
                <div style={{width:"100%",background:C.grayPale,borderRadius:4,display:"flex",alignItems:"flex-end",height:64,overflow:"hidden"}}>
                  <div style={{width:"100%",height:d.total>0?pct+"%":"3px",background:isToday?C.blue:C.bluePale,borderRadius:4,transition:"height .4s"}}/>
                </div>
                <div style={{fontSize:period==="week"?10:8,color:isToday?C.blue:C.textLight,fontWeight:isToday?700:400}}>{d.label}</div>
              </div>
            );
          })}
        </div>
      </Card>

      {/* Group breakdown bar */}
      <Card>
        <div style={{fontWeight:700,fontSize:14,color:C.text,marginBottom:12}}>🗂️ แยกตามหมวด</div>
        {groupTotals.length===0?<div style={{color:C.textLight,fontSize:13,textAlign:"center",padding:8}}>ไม่มีข้อมูล</div>:
        groupTotals.map((g,i)=>(
          <div key={i} style={{marginBottom:10}}>
            <div style={{display:"flex",justifyContent:"space-between",fontSize:13,marginBottom:4}}>
              <span style={{fontWeight:600,color:groupColor[g.group]||C.gray}}>{g.group}</span>
              <span style={{fontWeight:700,color:C.text}}>฿{fmt(g.total)}</span>
            </div>
            <div style={{background:C.grayPale,borderRadius:8,height:10,overflow:"hidden"}}>
              <div style={{width:(g.total/maxG*100)+"%",height:"100%",background:groupColor[g.group]||C.gray,borderRadius:8,transition:"width .5s"}}/>
            </div>
          </div>
        ))}
      </Card>

      {/* Branch comparison */}
      <Card>
        <div style={{fontWeight:700,fontSize:14,color:C.text,marginBottom:12}}>🏭 เปรียบเทียบสาขา</div>
        <div style={{display:"flex",gap:12,alignItems:"flex-end",height:80}}>
          {branchTotals.map((b,i)=>{
            const pct=Math.max(8,(b.total/maxBranch)*100);
            return (
              <div key={i} style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",gap:4}}>
                <div style={{fontSize:12,fontWeight:700,color:C.blue}}>฿{fmt(b.total)}</div>
                <div style={{width:"100%",background:C.grayPale,borderRadius:8,display:"flex",alignItems:"flex-end",height:56,overflow:"hidden"}}>
                  <div style={{width:"100%",height:pct+"%",background:i===0?C.blue:C.teal,borderRadius:8}}/>
                </div>
                <div style={{fontSize:12,color:C.textMid,fontWeight:600}}>{b.branch}</div>
              </div>
            );
          })}
        </div>
      </Card>

      {/* Type breakdown table — filtered */}
      {filterGroup!=="ทั้งหมด" && (
        <Card>
          <div style={{fontWeight:700,fontSize:14,color:C.text,marginBottom:12}}>
            🔬 เจาะลึก: {filterGroup}
          </div>
          {(EXPENSE_CATS.find(c=>c.group===filterGroup)?.items||[]).map(t=>{
            const total = periodExp.filter(e=>e.type===t).reduce((s,e)=>s+e.amount,0);
            if(total===0) return null;
            const pct = (total/Math.max(periodTotal,1)*100).toFixed(0);
            const gc = groupColor[filterGroup]||C.gray;
            return (
              <div key={t} style={{marginBottom:10}}>
                <div style={{display:"flex",justifyContent:"space-between",fontSize:12,marginBottom:3}}>
                  <span style={{color:C.textMid}}>{t}</span>
                  <span style={{fontWeight:700,color:gc}}>฿{fmt(total)} <span style={{color:C.textLight,fontWeight:400}}>({pct}%)</span></span>
                </div>
                <div style={{background:C.grayPale,borderRadius:6,height:8,overflow:"hidden"}}>
                  <div style={{width:pct+"%",height:"100%",background:gc,borderRadius:6}}/>
                </div>
              </div>
            );
          })}
        </Card>
      )}

      {/* Person breakdown — filtered */}
      {filterPerson!=="ทั้งหมด" && (
        <Card style={{background:C.purplePale}}>
          <div style={{fontWeight:700,fontSize:14,color:C.purple,marginBottom:12}}>👤 สรุปของ {filterPerson}</div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
            <div style={{background:C.white,borderRadius:10,padding:"10px",textAlign:"center"}}>
              <div style={{fontSize:10,color:C.textMid}}>ยอดรวม</div>
              <div style={{fontWeight:700,fontSize:18,color:C.purple}}>฿{fmt(periodExp.filter(e=>e.orderedBy===filterPerson).reduce((s,e)=>s+e.amount,0))}</div>
            </div>
            <div style={{background:C.white,borderRadius:10,padding:"10px",textAlign:"center"}}>
              <div style={{fontSize:10,color:C.textMid}}>ครั้ง</div>
              <div style={{fontWeight:700,fontSize:18,color:C.purple}}>{periodExp.filter(e=>e.orderedBy===filterPerson).length}</div>
            </div>
          </div>
        </Card>
      )}

      {/* Recent list */}
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
        <div style={{fontWeight:700,fontSize:14,color:C.text}}>รายการล่าสุด</div>
        <button onClick={()=>setTab("list")} style={{fontSize:12,color:C.blue,background:"none",border:"none",cursor:"pointer",fontWeight:600}}>ดูทั้งหมด ›</button>
      </div>
      {filtered.slice(0,3).map(e=>{
        const gc=groupColor[e.group]||C.gray; const gp=groupPale[e.group]||C.grayPale;
        return (
          <div key={e.id} style={{background:C.white,borderRadius:14,marginBottom:8,border:`1.5px solid ${gc}22`,overflow:"hidden",display:"flex"}}>
            <div style={{width:60,flexShrink:0,background:gp,display:"flex",alignItems:"center",justifyContent:"center",fontSize:22}}>
              {e.imgs.length>0?<img src={e.imgs[0]} style={{width:"100%",height:"100%",objectFit:"cover"}} alt=""/>:
                <span>{e.group==="น้ำมัน"?"⛽":e.group==="ซ่อมบำรุง"?"🔧":"💳"}</span>}
            </div>
            <div style={{flex:1,padding:"9px 12px",minWidth:0}}>
              <div style={{display:"flex",justifyContent:"space-between"}}>
                <div style={{fontSize:13,fontWeight:600,color:C.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",flex:1}}>{e.desc}</div>
                <span style={{fontWeight:700,color:gc,fontSize:13,marginLeft:8}}>฿{fmt(e.amount)}</span>
              </div>
              <div style={{fontSize:11,color:C.textLight,marginTop:2}}>
                {e.date} · {e.branch} · 👤{e.orderedBy} · จาก:{e.paidFrom}
              </div>
            </div>
          </div>
        );
      })}
      {filtered.length===0&&<div style={{textAlign:"center",color:C.textLight,padding:24}}>ยังไม่มีรายการ</div>}
    </div>
  );
}

// ─── TOOLS INVENTORY ──────────────────────────────────────────
function ToolsInvPage({lang="th"}) {
  const [tools, setTools] = useState(TOOLS_INV);
  const [txns, setTxns] = useState(INIT_TOOL_TXN);
  const [view, setView] = useState("stock");
  const [filterStore, setFilterStore] = useState("ทั้งหมด");
  const [form, setForm] = useState({ name:"", cat:"ไฟฟ้า", store:"JK1", qty:"", minQty:"1", serial:"", img:"🔧" });
  const [txnForm, setTxnForm] = useState({ toolId:"", type:"เข้า", qty:"1", recorder:"", borrower:"", returnDate:"", note:"" });

  const addTool = () => {
    if (!form.name) return;
    setTools(prev => [...prev, { id:Date.now(), ...form, qty:+form.qty, minQty:+form.minQty }]);
    setForm({ name:"", cat:"ไฟฟ้า", store:"JK1", qty:"", minQty:"1", serial:"", img:"🔧" });
    setView("stock");
  };

  const addTxn = () => {
    if (!txnForm.toolId || !txnForm.qty) return;
    const tool = tools.find(tt => tt.id === +txnForm.toolId);
    if (!tool) return;
    const qty = +txnForm.qty;
    const newBal = txnForm.type === "เข้า" || txnForm.type === "คืน" ? tool.qty + qty : Math.max(0, tool.qty - qty);
    const id = "TOOL-" + String(Date.now()).slice(-6);
    setTxns(prev => [{ id, date:today(), toolId:tool.id, toolName:tool.name, cat:tool.cat, store:tool.store, serial:tool.serial||"", ...txnForm, qty, balance:newBal, time:new Date().toLocaleString("th-TH") }, ...prev]);
    setTools(prev => prev.map(tt => tt.id===tool.id ? { ...tt, qty:newBal } : tt));
    setTxnForm({ toolId:"", type:"เข้า", qty:"1", recorder:"", borrower:"", returnDate:"", note:"" });
    setView("txn");
  };

  const typeColor = tp => tp==="เข้า"?"#2A9078":tp==="ยืม"?C.blue:tp==="คืน"?C.teal:C.red;
  const typeBg    = tp => tp==="เข้า"?C.tealPale:tp==="ยืม"?C.bluePale:tp==="คืน"?"#EAF6F3":C.redPale;

  return (
    <div>
      <SectionTitle icon="📦" title="ห้องอุปกรณ์" color={C.gray}/>

      <div style={{display:"flex",gap:6,marginBottom:14}}>
        {[["stock","📦 สต็อก"],["txn","📋 ประวัติ"]].map(([k,lbl])=>(
          <button key={k} onClick={()=>setView(k)} style={{
            flex:1,padding:"9px",borderRadius:10,border:"1.5px solid",fontSize:13,fontWeight:600,cursor:"pointer",
            borderColor:view===k?C.gray:C.greenMid,background:view===k?C.gray:C.white,color:view===k?C.white:C.textMid,
          }}>{lbl}</button>
        ))}
      </div>

      {view==="stock" && (
        <>
          <div style={{display:"flex",gap:6,marginBottom:14}}>
            {["ทั้งหมด","JK1","JK2"].map(s=>(
              <button key={s} onClick={()=>setFilterStore(s)} style={{
                flex:1,padding:"8px",borderRadius:10,border:"1.5px solid",fontSize:13,fontWeight:600,cursor:"pointer",
                borderColor:filterStore===s?C.gray:C.greenMid,background:filterStore===s?C.gray:C.white,color:filterStore===s?C.white:C.textMid,
              }}>{s}</button>
            ))}
          </div>
          {tools.filter(tt=>filterStore==="ทั้งหมด"||tt.store===filterStore).map(tt=>{
            const low = tt.qty <= (tt.minQty||0);
            return (
              <Card key={tt.id} style={{border:`1.5px solid ${low?C.red:C.greenMid}`,padding:0,overflow:"hidden",display:"flex",marginBottom:10}}>
                <div style={{width:72,flexShrink:0,background:C.grayPale,display:"flex",alignItems:"center",justifyContent:"center",fontSize:28}}>{tt.img}</div>
                <div style={{flex:1,padding:"12px"}}>
                  <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:4}}>
                    <div>
                      <div style={{fontWeight:700,fontSize:14,color:C.text}}>{tt.name}</div>
                      <div style={{fontSize:11,color:C.textLight}}>{tt.cat} · คลัง {tt.store}</div>
                      {tt.serial && <div style={{fontSize:10,color:C.textLight,fontFamily:"monospace"}}>S/N: {tt.serial}</div>}
                    </div>
                    <div style={{textAlign:"center"}}>
                      <div style={{fontWeight:700,fontSize:20,color:low?C.red:C.gray}}>{tt.qty}</div>
                      <div style={{fontSize:10,color:C.textLight}}>ชิ้น</div>
                    </div>
                  </div>
                  {low && <Pill label="ใกล้หมด" color={C.red} bg={C.redPale}/>}
                </div>
              </Card>
            );
          })}
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginTop:4}}>
            <button onClick={()=>setView("add_txn")} style={{padding:"13px",borderRadius:12,border:`2px solid ${C.gray}`,background:C.gray,color:C.white,fontSize:14,fontWeight:700,cursor:"pointer"}}>+ ยืม/คืน/รับ</button>
            <button onClick={()=>setView("add_tool")} style={{padding:"13px",borderRadius:12,border:`2px dashed ${C.gray}`,background:C.grayPale,color:C.gray,fontSize:14,fontWeight:700,cursor:"pointer"}}>+ เพิ่มอุปกรณ์</button>
          </div>
        </>
      )}

      {view==="txn" && (
        <>
          <button onClick={()=>setView("add_txn")} style={{width:"100%",padding:"11px",borderRadius:12,border:`2px solid ${C.gray}`,background:C.gray,color:C.white,fontSize:14,fontWeight:700,cursor:"pointer",marginBottom:12}}>+ บันทึกการยืม/คืน/รับ</button>
          {txns.map(tx=>(
            <Card key={tx.id} style={{border:`1.5px solid ${typeBg(tx.type)}`,padding:"12px",marginBottom:8}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:4}}>
                <div>
                  <div style={{fontWeight:700,fontSize:13,color:C.text}}>{tx.toolName}</div>
                  {tx.serial && <div style={{fontSize:10,color:C.textLight,fontFamily:"monospace"}}>S/N: {tx.serial}</div>}
                  <div style={{fontSize:11,color:C.textMid}}>{tx.store} · {tx.date}</div>
                </div>
                <div style={{textAlign:"right"}}>
                  <Pill label={tx.type} color={typeColor(tx.type)} bg={typeBg(tx.type)}/>
                  <div style={{fontWeight:700,fontSize:16,color:typeColor(tx.type),marginTop:4}}>{tx.qty} ชิ้น</div>
                </div>
              </div>
              <div style={{fontSize:11,color:C.textMid,borderTop:`1px solid ${C.greenMid}`,paddingTop:6,marginTop:4,display:"grid",gridTemplateColumns:"1fr 1fr",gap:4}}>
                <span>คงเหลือ: <b>{tx.balance} ชิ้น</b></span>
                <span>ผู้บันทึก: {tx.recorder||"—"}</span>
                {tx.borrower && <span>ผู้ยืม: <b>{tx.borrower}</b></span>}
                {tx.returnDate && <span>กำหนดคืน: {tx.returnDate}</span>}
                {tx.note && <span style={{gridColumn:"1/-1"}}>หมายเหตุ: {tx.note}</span>}
              </div>
            </Card>
          ))}
          {txns.length===0 && <div style={{textAlign:"center",color:C.textLight,padding:30}}>ยังไม่มีประวัติ</div>}
        </>
      )}

      {view==="add_tool" && (
        <Card>
          <div style={{fontWeight:700,marginBottom:10,color:C.text,fontSize:15}}>เพิ่มอุปกรณ์ใหม่</div>
          <label style={LS}>ชื่ออุปกรณ์</label>
          <input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} style={{...IS,marginBottom:8}}/>
          <label style={LS}>Serial / รหัสเครื่อง (ถ้ามี)</label>
          <input value={form.serial} onChange={e=>setForm({...form,serial:e.target.value})} style={{...IS,marginBottom:8}} placeholder="SN-XXXX-001"/>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:8,marginBottom:10}}>
            <div><label style={LS}>ประเภท</label>
              <select value={form.cat} onChange={e=>setForm({...form,cat:e.target.value})} style={IS}>
                {["ไฟฟ้า","ลม","ทั่วไป","ยานพาหนะ"].map(c=><option key={c}>{c}</option>)}
              </select>
            </div>
            <div><label style={LS}>คลัง</label>
              <select value={form.store} onChange={e=>setForm({...form,store:e.target.value})} style={IS}>
                <option>JK1</option><option>JK2</option>
              </select>
            </div>
            <div><label style={LS}>จำนวน</label>
              <input type="number" value={form.qty} onChange={e=>setForm({...form,qty:e.target.value})} style={IS}/>
            </div>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
            <button onClick={()=>setView("stock")} style={{padding:"11px",borderRadius:10,border:`1.5px solid ${C.greenMid}`,background:C.white,color:C.textMid,cursor:"pointer"}}>ยกเลิก</button>
            <button onClick={addTool} style={{padding:"11px",borderRadius:10,border:"none",background:C.gray,color:C.white,fontWeight:700,cursor:"pointer"}}>บันทึก</button>
          </div>
        </Card>
      )}

      {view==="add_txn" && (
        <Card>
          <div style={{fontWeight:700,marginBottom:10,color:C.text,fontSize:15}}>บันทึกรับ/ยืม/คืนอุปกรณ์</div>
          <label style={LS}>อุปกรณ์</label>
          <select value={txnForm.toolId} onChange={e=>setTxnForm({...txnForm,toolId:e.target.value})} style={{...IS,marginBottom:8}}>
            <option value="">-- เลือกอุปกรณ์ --</option>
            {tools.map(tt=><option key={tt.id} value={tt.id}>{tt.name}</option>)}
          </select>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:8}}>
            <div><label style={LS}>ประเภท</label>
              <select value={txnForm.type} onChange={e=>setTxnForm({...txnForm,type:e.target.value})} style={IS}>
                {["เข้า","ออก","ยืม","คืน"].map(tp=><option key={tp}>{tp}</option>)}
              </select>
            </div>
            <div><label style={LS}>จำนวน</label>
              <input type="number" value={txnForm.qty} onChange={e=>setTxnForm({...txnForm,qty:e.target.value})} style={IS}/>
            </div>
          </div>
          <label style={LS}>ผู้บันทึก</label>
          <input value={txnForm.recorder} onChange={e=>setTxnForm({...txnForm,recorder:e.target.value})} style={{...IS,marginBottom:8}}/>
          {txnForm.type==="ยืม" && (
            <>
              <label style={LS}>ชื่อผู้ยืม</label>
              <input value={txnForm.borrower} onChange={e=>setTxnForm({...txnForm,borrower:e.target.value})} style={{...IS,marginBottom:8}}/>
              <label style={LS}>กำหนดคืน</label>
              <input type="date" value={txnForm.returnDate} onChange={e=>setTxnForm({...txnForm,returnDate:e.target.value})} style={{...IS,marginBottom:8}}/>
            </>
          )}
          <label style={LS}>หมายเหตุ</label>
          <input value={txnForm.note} onChange={e=>setTxnForm({...txnForm,note:e.target.value})} style={{...IS,marginBottom:12}}/>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
            <button onClick={()=>setView("txn")} style={{padding:"11px",borderRadius:10,border:`1.5px solid ${C.greenMid}`,background:C.white,color:C.textMid,cursor:"pointer"}}>ยกเลิก</button>
            <button onClick={addTxn} style={{padding:"11px",borderRadius:10,border:"none",background:C.gray,color:C.white,fontWeight:700,cursor:"pointer"}}>บันทึก</button>
          </div>
        </Card>
      )}
    </div>
  );
}

// ─── TASK MANAGEMENT PAGE ────────────────────────────────────
const TASK_CATS = ["ซ่อมบำรุง","ชั่งน้ำหนัก","ฉีดวัคซีน","ทำความสะอาด","บันทึกข้อมูล","ตรวจสอบ","อื่นๆ"];
const TASK_PRIORITY = ["สูง","กลาง","ต่ำ"];
const TASK_STATUS = ["รอดำเนินการ","กำลังดำเนินการ","เสร็จแล้ว","ยกเลิก"];

function TaskPage({lang="th"}) {
  const [tasks, setTasks] = useState(INIT_TASKS);
  const [showAdd, setShowAdd] = useState(false);
  const [filterStatus, setFilterStatus] = useState("ทั้งหมด");
  const [form, setForm] = useState({ title:"", desc:"", assignedBy:"", assignedTo:"", farm:FARMS[0], house:"เล้า 1", cat:"ซ่อมบำรุง", dueDate:today(), priority:"กลาง", note:"" });

  const priorityColor = p => p==="สูง"?C.red:p==="กลาง"?C.orange:C.teal;
  const priorityBg    = p => p==="สูง"?C.redPale:p==="กลาง"?C.orangePale:C.tealPale;
  const statusColor   = s => s==="เสร็จแล้ว"?C.teal:s==="กำลังดำเนินการ"?C.blue:s==="ยกเลิก"?C.gray:C.orange;

  const statuses = ["ทั้งหมด", ...TASK_STATUS];
  const filtered = filterStatus==="ทั้งหมด" ? tasks : tasks.filter(tk=>tk.status===filterStatus);

  const addTask = () => {
    if (!form.title) return;
    setTasks(prev => [{ id:"TASK-"+String(Date.now()).slice(-6), createdDate:today(), ...form, status:"รอดำเนินการ", progress:0, time:new Date().toLocaleString("th-TH") }, ...prev]);
    setForm({ title:"", desc:"", assignedBy:"", assignedTo:"", farm:FARMS[0], house:"เล้า 1", cat:"ซ่อมบำรุง", dueDate:today(), priority:"กลาง", note:"" });
    setShowAdd(false);
  };

  const updateProgress = (id, val) =>
    setTasks(prev => prev.map(tk => tk.id===id ? {...tk, progress:Math.max(0,Math.min(100,val))} : tk));

  const updateStatus = (id, status) =>
    setTasks(prev => prev.map(tk => tk.id===id ? {...tk, status, progress:status==="เสร็จแล้ว"?100:tk.progress} : tk));

  return (
    <div>
      <SectionTitle icon="✅" title="งานที่มอบหมาย" color={C.purple}/>

      <div style={{overflowX:"auto",marginBottom:12}}>
        <div style={{display:"flex",gap:6,paddingBottom:4}}>
          {statuses.map(s=>(
            <button key={s} onClick={()=>setFilterStatus(s)} style={{
              flexShrink:0,padding:"7px 12px",borderRadius:10,border:"1.5px solid",fontSize:12,fontWeight:600,cursor:"pointer",
              borderColor:filterStatus===s?C.purple:C.greenMid,background:filterStatus===s?C.purple:C.white,color:filterStatus===s?C.white:C.textMid,
            }}>{s}</button>
          ))}
        </div>
      </div>

      {filtered.map(task=>(
        <Card key={task.id} style={{border:`1.5px solid ${priorityBg(task.priority)}`,marginBottom:10}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:6}}>
            <div style={{flex:1,paddingRight:8}}>
              <div style={{fontWeight:700,fontSize:14,color:C.text}}>{task.title}</div>
              <div style={{fontSize:11,color:C.textMid}}>{task.farm} — {task.house} · {task.cat}</div>
              {task.desc && <div style={{fontSize:12,color:C.textMid,marginTop:2}}>{task.desc}</div>}
            </div>
            <Pill label={task.priority} color={priorityColor(task.priority)} bg={priorityBg(task.priority)}/>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:4,marginBottom:8,fontSize:11,color:C.textMid}}>
            <span>มอบหมายโดย: <b>{task.assignedBy}</b></span>
            <span>ผู้รับงาน: <b>{task.assignedTo}</b></span>
            <span>กำหนดส่ง: <b style={{color:new Date(task.dueDate)<new Date()&&task.status!=="เสร็จแล้ว"?C.red:C.text}}>{task.dueDate}</b></span>
            <span>สร้าง: {task.createdDate}</span>
          </div>
          <div style={{marginBottom:8}}>
            <div style={{display:"flex",justifyContent:"space-between",fontSize:11,color:C.textMid,marginBottom:4}}>
              <span>ความคืบหน้า</span>
              <span style={{fontWeight:700,color:task.progress>=100?C.teal:C.text}}>{task.progress}%</span>
            </div>
            <div style={{background:C.greenMid,borderRadius:6,height:8,overflow:"hidden"}}>
              <div style={{height:"100%",borderRadius:6,background:task.progress>=100?C.teal:C.blue,width:`${task.progress}%`,transition:"width .3s"}}/>
            </div>
            <input type="range" min="0" max="100" value={task.progress}
              onChange={e=>updateProgress(task.id,+e.target.value)}
              style={{width:"100%",marginTop:4,accentColor:C.blue}}/>
          </div>
          <div style={{display:"flex",gap:5,flexWrap:"wrap"}}>
            {TASK_STATUS.map(s=>(
              <button key={s} onClick={()=>updateStatus(task.id,s)} style={{
                padding:"5px 9px",borderRadius:8,border:"1.5px solid",fontSize:11,fontWeight:600,cursor:"pointer",
                borderColor:task.status===s?statusColor(s):C.greenMid,
                background:task.status===s?statusColor(s):C.white,
                color:task.status===s?C.white:C.textMid,
              }}>{s}</button>
            ))}
          </div>
        </Card>
      ))}

      {filtered.length===0 && <div style={{textAlign:"center",color:C.textLight,padding:30}}>ไม่มีงานในสถานะนี้</div>}

      {showAdd ? (
        <Card>
          <div style={{fontWeight:700,marginBottom:10,color:C.text,fontSize:15}}>เพิ่มงานใหม่</div>
          <label style={LS}>ชื่องาน</label>
          <input value={form.title} onChange={e=>setForm({...form,title:e.target.value})} style={{...IS,marginBottom:8}} placeholder="เช่น ตรวจระบบน้ำเล้า 1"/>
          <label style={LS}>รายละเอียด</label>
          <input value={form.desc} onChange={e=>setForm({...form,desc:e.target.value})} style={{...IS,marginBottom:8}}/>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:8}}>
            <div><label style={LS}>ฟาร์ม</label>
              <select value={form.farm} onChange={e=>setForm({...form,farm:e.target.value,house:"เล้า 1"})} style={IS}>
                {FARMS.map(f=><option key={f}>{f}</option>)}
              </select>
            </div>
            <div><label style={LS}>เล้า</label>
              <select value={form.house} onChange={e=>setForm({...form,house:e.target.value})} style={IS}>
                {(HOUSES[form.farm]||[]).map(h=><option key={h}>{h}</option>)}
              </select>
            </div>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:8}}>
            <div><label style={LS}>ประเภทงาน</label>
              <select value={form.cat} onChange={e=>setForm({...form,cat:e.target.value})} style={IS}>
                {TASK_CATS.map(c=><option key={c}>{c}</option>)}
              </select>
            </div>
            <div><label style={LS}>ความสำคัญ</label>
              <select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})} style={IS}>
                {TASK_PRIORITY.map(p=><option key={p}>{p}</option>)}
              </select>
            </div>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:8}}>
            <div><label style={LS}>มอบหมายโดย</label>
              <input value={form.assignedBy} onChange={e=>setForm({...form,assignedBy:e.target.value})} style={IS}/>
            </div>
            <div><label style={LS}>ผู้รับงาน</label>
              <input value={form.assignedTo} onChange={e=>setForm({...form,assignedTo:e.target.value})} style={IS}/>
            </div>
          </div>
          <label style={LS}>กำหนดส่ง</label>
          <input type="date" value={form.dueDate} onChange={e=>setForm({...form,dueDate:e.target.value})} style={{...IS,marginBottom:8}}/>
          <label style={LS}>หมายเหตุ</label>
          <input value={form.note} onChange={e=>setForm({...form,note:e.target.value})} style={{...IS,marginBottom:12}}/>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
            <button onClick={()=>setShowAdd(false)} style={{padding:"11px",borderRadius:10,border:`1.5px solid ${C.greenMid}`,background:C.white,color:C.textMid,cursor:"pointer"}}>ยกเลิก</button>
            <button onClick={addTask} style={{padding:"11px",borderRadius:10,border:"none",background:C.purple,color:C.white,fontWeight:700,cursor:"pointer"}}>บันทึก</button>
          </div>
        </Card>
      ) : (
        <button onClick={()=>setShowAdd(true)} style={{width:"100%",padding:"13px",borderRadius:12,border:`2px dashed ${C.purple}`,background:C.purplePale,color:C.purple,fontSize:14,fontWeight:700,cursor:"pointer",marginTop:8}}>
          + เพิ่มงานใหม่
        </button>
      )}
    </div>
  );
}

