function KookKai({setPage, lang="th"}) {
  const [open, setOpen]     = useState(false);
  const [step, setStep]     = useState(0);
  const [typing, setTyping] = useState(false);
  const [shown, setShown]   = useState("");

  const guide = GUIDE_STEPS[step];
  const msg   = guide?.[lang] || guide?.th || "";

  // Typewriter effect
  useEffect(() => {
    if(!open) return;
    setShown("");
    setTyping(true);
    let i = 0;
    const iv = setInterval(() => {
      i++;
      setShown(msg.slice(0, i));
      if(i >= msg.length) { setTyping(false); clearInterval(iv); }
    }, 18);
    return () => clearInterval(iv);
  }, [open, step, lang]);

  const goPage = () => {
    if(guide?.page) setPage(guide.page);
    setOpen(false);
  };

  return (
    <>
      {/* Floating bot button */}
      <button onClick={()=>{setOpen(!open); setShown(""); setTyping(true);}}
        style={{
          position:"fixed", bottom:76, right:16, zIndex:150,
          width:58, height:58, borderRadius:"50%", border:"none",
          background:"linear-gradient(135deg,#1A6BB5,#0D4A8A)",
          boxShadow:"0 4px 16px rgba(26,107,181,0.45)",
          cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center",
          fontSize:28, transition:"transform .2s",
        }}>
        🐔
        {!open && (
          <div style={{position:"absolute",top:-4,right:-4,background:C.orange,borderRadius:"50%",width:18,height:18,display:"flex",alignItems:"center",justifyContent:"center",fontSize:10,fontWeight:700,color:"#fff"}}>
            {GUIDE_STEPS.length}
          </div>
        )}
      </button>

      {/* Chat bubble */}
      {open && (
        <div style={{
          position:"fixed", bottom:144, right:12, zIndex:150,
          width:290, background:C.white, borderRadius:20,
          boxShadow:"0 8px 32px rgba(0,0,0,0.18)",
          border:`1.5px solid ${C.greenMid}`, overflow:"hidden"
        }}>
          {/* Header */}
          <div style={{background:"linear-gradient(135deg,#1A6BB5,#0D4A8A)",padding:"10px 14px",display:"flex",alignItems:"center",gap:8}}>
            {/* น้องกุ๊กไก่ avatar */}
            <div style={{width:38,height:38,borderRadius:"50%",background:"#fff",display:"flex",alignItems:"center",justifyContent:"center",fontSize:22,flexShrink:0}}>
              🐔
            </div>
            <div style={{flex:1}}>
              <div style={{color:"#fff",fontWeight:700,fontSize:13}}>น้องกุ๊กไก่</div>
              <div style={{color:"rgba(255,255,255,0.8)",fontSize:10}}>บอตเลขา · Junkum Farm</div>
            </div>
            <button onClick={()=>setOpen(false)} style={{background:"rgba(255,255,255,0.2)",border:"none",color:"#fff",borderRadius:"50%",width:24,height:24,cursor:"pointer",fontSize:13}}>×</button>
          </div>

          {/* Message */}
          <div style={{padding:"12px 14px"}}>
            <div style={{display:"flex",gap:8,alignItems:"flex-start",marginBottom:12}}>
              <div style={{fontSize:20,flexShrink:0}}>🐔</div>
              <div style={{background:C.greenPale,borderRadius:"4px 14px 14px 14px",padding:"8px 12px",fontSize:13,color:C.ink,lineHeight:1.5,minHeight:40}}>
                <span style={{fontSize:16,marginRight:6}}>{guide?.icon}</span>
                {shown}
                {typing && <span style={{animation:"blink 0.8s infinite",opacity:0.5}}>▌</span>}
              </div>
            </div>

            {/* Step dots */}
            <div style={{display:"flex",justifyContent:"center",gap:4,marginBottom:10}}>
              {GUIDE_STEPS.map((_,i)=>(
                <button key={i} onClick={()=>{setStep(i);setShown("");setTyping(true);}}
                  style={{width:i===step?16:6,height:6,borderRadius:3,border:"none",cursor:"pointer",
                    background:i===step?C.green:C.greenMid,transition:"all .2s"}}/>
              ))}
            </div>

            {/* Actions */}
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:6}}>
              <button onClick={()=>{if(step>0){setStep(s=>s-1);setShown("");setTyping(true);}}}
                disabled={step===0}
                style={{padding:"7px 4px",borderRadius:10,border:`1.5px solid ${C.greenMid}`,background:C.white,color:step===0?C.textLight:C.ink,fontSize:12,cursor:step===0?"not-allowed":"pointer"}}>
                ←
              </button>
              <button onClick={goPage}
                style={{padding:"7px 4px",borderRadius:10,border:"none",background:C.green,color:"#fff",fontSize:11,fontWeight:700,cursor:"pointer"}}>
                ไปดู!
              </button>
              <button onClick={()=>{if(step<GUIDE_STEPS.length-1){setStep(s=>s+1);setShown("");setTyping(true);}}}
                disabled={step===GUIDE_STEPS.length-1}
                style={{padding:"7px 4px",borderRadius:10,border:`1.5px solid ${C.greenMid}`,background:C.white,color:step===GUIDE_STEPS.length-1?C.textLight:C.ink,fontSize:12,cursor:step===GUIDE_STEPS.length-1?"not-allowed":"pointer"}}>
                →
              </button>
            </div>
          </div>
          <style>{`@keyframes blink{0%,100%{opacity:1}50%{opacity:0}}`}</style>
        </div>
      )}
    </>
  );
}


