// ─── CONFETTI ────────────────────────────────────────────────
function Confetti() {
  const pieces = Array.from({length:60},(_,i)=>({
    id:i,
    x: Math.random()*100,
    delay: Math.random()*1.5,
    dur: 1.5 + Math.random()*2,
    color: ["#FFD700","#FF6B6B","#4ECDC4","#45B7D1","#96CEB4","#FFEAA7","#DDA0DD","#98D8C8"][i%8],
    size: 6 + Math.random()*8,
    rot: Math.random()*360,
  }));
  return (
    <div style={{position:"fixed",inset:0,pointerEvents:"none",zIndex:999,overflow:"hidden"}}>
      {pieces.map(p=>(
        <div key={p.id} style={{
          position:"absolute",
          left:p.x+"%",
          top:"-20px",
          width:p.size,
          height:p.size,
          background:p.color,
          borderRadius:p.id%3===0?"50%":p.id%3===1?"2px":"0",
          transform:`rotate(${p.rot}deg)`,
          animation:`fall_${p.id%5} ${p.dur}s ${p.delay}s ease-in forwards`,
          opacity:0.9,
        }}/>
      ))}
      <style>{`
        @keyframes fall_0{0%{transform:translateY(0) rotate(0deg);opacity:1}100%{transform:translateY(110vh) rotate(720deg);opacity:0}}
        @keyframes fall_1{0%{transform:translateY(0) rotate(0deg) translateX(0);opacity:1}50%{transform:translateY(50vh) rotate(360deg) translateX(30px)}100%{transform:translateY(110vh) rotate(720deg) translateX(-20px);opacity:0}}
        @keyframes fall_2{0%{transform:translateY(0) rotate(0deg) translateX(0);opacity:1}50%{transform:translateY(55vh) rotate(180deg) translateX(-40px)}100%{transform:translateY(110vh) rotate(540deg) translateX(20px);opacity:0}}
        @keyframes fall_3{0%{transform:translateY(0) scale(1) rotate(0deg);opacity:1}100%{transform:translateY(110vh) scale(0.3) rotate(1080deg);opacity:0}}
        @keyframes fall_4{0%{transform:translateY(0) rotate(0deg);opacity:1}30%{transform:translateY(30vh) rotate(200deg) translateX(50px)}70%{transform:translateY(70vh) rotate(400deg) translateX(-30px)}100%{transform:translateY(110vh) rotate(720deg);opacity:0}}
      `}</style>
    </div>
  );
}

