// Albums: {id, branch, batchName, house, date, photos:[{url,count,date,basket}]}
const INIT_ALBUMS = [
  { id:1, branch:"JK2 - ลพบุรี", batchName:"รุ่น 2/68", house:"เล้า 1", date:"2025-06-01", photos:[] },
];
const HOUSES_BY_BRANCH = {
  "JK1 - สระบุรี": ["เล้า 1","เล้า 2"],
  "JK2 - ลพบุรี":  ["เล้า 1","เล้า 2","เล้า 3","เล้า 4","เล้า 5","เล้า 6","เล้า 7"],
};

// ─── ALBUM BROWSER COMPONENT ─────────────────────────────────
function AlbumBrowser({albums, setAlbums, showNewAlbum, setShowNewAlbum, newAlbumName, setNewAlbumName}) {
  const [selBranch, setSelBranch]   = useState("ทั้งหมด");
  const [selBatch, setSelBatch]     = useState("ทั้งหมด");
  const [selHouse, setSelHouse]     = useState(null);    // {albumId} drill into house
  const [newForm, setNewForm]       = useState({branch:"JK2 - ลพบุรี", batchName:"", house:"เล้า 1"});
  const [lightbox, setLightbox]     = useState(null);    // photo object

  // Branches
  const branches = ["ทั้งหมด","JK1 - สระบุรี","JK2 - ลพบุรี"];

  // Filter albums
  const filtered = albums.filter(a => {
    if(selBranch !== "ทั้งหมด" && a.branch !== selBranch) return false;
    if(selBatch  !== "ทั้งหมด" && a.batchName !== selBatch) return false;
    return true;
  });

  // All batch names for filter
  const allBatches = [...new Set(albums.map(a=>a.batchName).filter(Boolean))];

  // Group by batchName for display
  const grouped = {};
  filtered.forEach(a => {
    const key = a.batchName || a.name || "ไม่ระบุรุ่น";
    if(!grouped[key]) grouped[key] = [];
    grouped[key].push(a);
  });

  const addAlbum = () => {
    if(!newForm.batchName) return;
    setAlbums(prev=>[...prev,{
      id:Date.now(), branch:newForm.branch,
      batchName:newForm.batchName, house:newForm.house,
      date:today(), photos:[]
    }]);
    setShowNewAlbum(false);
    setNewForm({branch:"JK2 - ลพบุรี", batchName:"", house:"เล้า 1"});
  };

  const totalAll = albums.reduce((s,a)=>s+a.photos.reduce((ss,p)=>ss+p.count,0),0);

  // ── HOUSE DETAIL VIEW ──
  if(selHouse) {
    const album = albums.find(a=>a.id===selHouse);
    if(!album) { setSelHouse(null); return null; }
    const total = album.photos.reduce((s,p)=>s+p.count,0);
    return (
      <div>
        <button onClick={()=>setSelHouse(null)} style={{background:"none",border:"none",color:C.green,fontWeight:700,fontSize:14,cursor:"pointer",padding:"0 0 14px",display:"flex",alignItems:"center",gap:4}}>
          ← กลับ
        </button>
        {/* Header */}
        <div style={{background:`linear-gradient(135deg,${C.green},${C.greenL})`,borderRadius:16,padding:"16px 18px",color:C.white,marginBottom:14}}>
          <div style={{fontSize:11,opacity:0.8}}>{album.branch}</div>
          <div style={{fontFamily:"serif",fontSize:20,fontWeight:700}}>{album.batchName}</div>
          <div style={{fontSize:13,opacity:0.85}}>{album.house}</div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:8,marginTop:12}}>
            {[[album.photos.length,"ตะกร้า"],[total,"ตัวรวม"],[album.photos.length>0?Math.round(total/album.photos.length):0,"เฉลี่ย/ตะกร้า"]].map(([v,l])=>(
              <div key={l} style={{background:"rgba(255,255,255,0.18)",borderRadius:10,padding:"8px",textAlign:"center"}}>
                <div style={{fontSize:20,fontWeight:700}}>{v}</div>
                <div style={{fontSize:10,opacity:0.8}}>{l}</div>
              </div>
            ))}
          </div>
        </div>

        {album.photos.length===0 && (
          <div style={{textAlign:"center",color:C.textLight,padding:40}}>ยังไม่มีรูป</div>
        )}

        {/* Gallery grid */}
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
          {album.photos.map((p,i)=>(
            <div key={i} onClick={()=>setLightbox(p)}
              style={{borderRadius:14,overflow:"hidden",background:C.white,boxShadow:"0 2px 10px rgba(0,0,0,0.08)",cursor:"pointer"}}>
              <img src={p.url} style={{width:"100%",height:130,objectFit:"cover",display:"block"}} alt=""/>
              <div style={{padding:"8px 10px"}}>
                <div style={{fontWeight:700,fontSize:13,color:C.text}}>ตะกร้าที่ {p.basket||i+1}</div>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginTop:3}}>
                  <div style={{fontSize:11,color:C.textLight}}>{p.date}</div>
                  <div style={{fontWeight:700,fontSize:14,color:C.green}}>{p.count} ตัว</div>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Total summary */}
        {album.photos.length>0 && (
          <div style={{background:C.greenPale,borderRadius:14,padding:"14px 16px",marginTop:14,border:`1.5px solid ${C.greenMid}`}}>
            <div style={{fontWeight:700,fontSize:14,color:C.text,marginBottom:8}}>📊 สรุปรุ่น {album.batchName} · {album.house}</div>
            {album.photos.map((p,i)=>(
              <div key={i} style={{display:"flex",justifyContent:"space-between",fontSize:13,padding:"4px 0",borderBottom:`1px dashed ${C.greenMid}`}}>
                <span style={{color:C.textMid}}>ตะกร้าที่ {p.basket||i+1}</span>
                <span style={{fontWeight:700,color:C.green}}>{p.count} ตัว</span>
              </div>
            ))}
            <div style={{display:"flex",justifyContent:"space-between",padding:"10px 0 0",fontWeight:700,fontSize:15}}>
              <span>รวมทั้งหมด</span>
              <span style={{color:C.green,fontSize:20}}>{total} ตัว</span>
            </div>
          </div>
        )}

        {/* Lightbox */}
        {lightbox && (
          <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.92)",zIndex:500,display:"flex",alignItems:"center",justifyContent:"center",flexDirection:"column"}}
               onClick={()=>setLightbox(null)}>
            <div style={{color:"rgba(255,255,255,0.5)",fontSize:12,marginBottom:8}}>แตะเพื่อปิด</div>
            <img src={lightbox.url} style={{width:"100%",maxWidth:480,maxHeight:"75vh",objectFit:"contain",borderRadius:12}} alt=""/>
            <div style={{background:"rgba(255,255,255,0.12)",borderRadius:10,padding:"10px 20px",marginTop:12,color:C.white,textAlign:"center"}}>
              <div style={{fontSize:14,fontWeight:700}}>ตะกร้าที่ {lightbox.basket} · {lightbox.count} ตัว</div>
              <div style={{fontSize:12,opacity:0.75}}>{lightbox.date}</div>
            </div>
          </div>
        )}
      </div>
    );
  }

  // ── MAIN ALBUM LIST ──
  return (
    <div>
      {/* Summary */}
      <div style={{background:`linear-gradient(135deg,${C.orange},#D4820A)`,borderRadius:14,padding:"12px 16px",color:C.white,marginBottom:14,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <div><div style={{fontSize:11,opacity:0.8}}>ไก่ทั้งหมดที่นับแล้ว</div><div style={{fontSize:28,fontWeight:700,fontFamily:"serif"}}>{totalAll.toLocaleString("th-TH")} ตัว</div></div>
        <div style={{textAlign:"right"}}><div style={{fontSize:11,opacity:0.8}}>จาก {albums.length} อัลบั้ม</div><div style={{fontSize:18,fontWeight:700}}>{albums.reduce((s,a)=>s+a.photos.length,0)} ตะกร้า</div></div>
      </div>

      {/* Branch filter */}
      <div style={{display:"flex",gap:6,marginBottom:10}}>
        {branches.map(b=>(
          <button key={b} onClick={()=>{setSelBranch(b);setSelBatch("ทั้งหมด");}} style={{
            flex:1,padding:"7px 4px",borderRadius:10,border:"1.5px solid",fontSize:11,fontWeight:600,cursor:"pointer",
            borderColor:selBranch===b?C.orange:C.greenMid,background:selBranch===b?C.orange:C.white,color:selBranch===b?C.white:C.textMid,
          }}>{b==="ทั้งหมด"?"ทั้งหมด":b.split(" - ")[0]}</button>
        ))}
      </div>

      {/* Batch filter */}
      {allBatches.length>1 && (
        <div style={{display:"flex",gap:5,flexWrap:"wrap",marginBottom:12}}>
          {["ทั้งหมด",...allBatches].map(b=>(
            <button key={b} onClick={()=>setSelBatch(b)} style={{
              padding:"5px 10px",borderRadius:8,border:"1.5px solid",fontSize:11,fontWeight:600,cursor:"pointer",
              borderColor:selBatch===b?C.green:C.greenMid,background:selBatch===b?C.green:C.white,color:selBatch===b?C.white:C.textMid,
            }}>{b}</button>
          ))}
        </div>
      )}

      {/* New album form */}
      {showNewAlbum && (
        <Card style={{marginBottom:12}}>
          <div style={{fontWeight:700,marginBottom:10,color:C.text}}>+ อัลบั้มใหม่</div>
          <label style={LS}>สาขา</label>
          <select value={newForm.branch} onChange={e=>setNewForm(f=>({...f,branch:e.target.value,house:HOUSES_BY_BRANCH[e.target.value][0]}))} style={{...IS,marginBottom:8}}>
            {Object.keys(HOUSES_BY_BRANCH).map(b=><option key={b}>{b}</option>)}
          </select>
          <label style={LS}>ชื่อรุ่น</label>
          <input value={newForm.batchName} onChange={e=>setNewForm(f=>({...f,batchName:e.target.value}))} placeholder="เช่น รุ่น 1/68" style={{...IS,marginBottom:8}}/>
          <label style={LS}>เล้า</label>
          <div style={{display:"flex",gap:5,flexWrap:"wrap",marginBottom:12}}>
            {HOUSES_BY_BRANCH[newForm.branch].map(h=>(
              <button key={h} onClick={()=>setNewForm(f=>({...f,house:h}))} style={{
                padding:"5px 10px",borderRadius:8,border:"1.5px solid",fontSize:12,fontWeight:600,cursor:"pointer",
                borderColor:newForm.house===h?C.orange:C.greenMid,background:newForm.house===h?C.orange:C.white,color:newForm.house===h?C.white:C.textMid,
              }}>{h}</button>
            ))}
          </div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
            <button onClick={()=>setShowNewAlbum(false)} style={{padding:"11px",borderRadius:10,border:`1.5px solid ${C.greenMid}`,background:C.white,color:C.textMid,cursor:"pointer"}}>{t("cancel",lang)}</button>
            <button onClick={addAlbum} style={{padding:"11px",borderRadius:10,border:"none",background:C.orange,color:C.white,fontWeight:700,cursor:"pointer"}}>สร้าง ✓</button>
          </div>
        </Card>
      )}

      {/* Grouped by batch */}
      {Object.keys(grouped).length===0 && <div style={{textAlign:"center",color:C.textLight,padding:32}}>ยังไม่มีอัลบั้ม</div>}
      {Object.entries(grouped).map(([batchName, batchAlbums])=>{
        const batchTotal = batchAlbums.reduce((s,a)=>s+a.photos.reduce((ss,p)=>ss+p.count,0),0);
        return (
          <div key={batchName} style={{marginBottom:16}}>
            {/* Batch header */}
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8,paddingBottom:6,borderBottom:`2px solid ${C.greenMid}`}}>
              <div style={{fontWeight:700,fontSize:15,color:C.text}}>🐥 {batchName}</div>
              <div style={{fontSize:12,color:C.green,fontWeight:700}}>รวม {batchTotal.toLocaleString("th-TH")} ตัว</div>
            </div>
            {/* House cards */}
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
              {batchAlbums.sort((a,b)=>a.house.localeCompare(b.house)).map(a=>{
                const hTotal = a.photos.reduce((s,p)=>s+p.count,0);
                return (
                  <button key={a.id} onClick={()=>setSelHouse(a.id)}
                    style={{background:C.white,borderRadius:14,padding:"12px",border:`1.5px solid ${C.greenMid}`,cursor:"pointer",textAlign:"left",boxShadow:"0 1px 6px rgba(0,0,0,0.05)"}}>
                    <div style={{fontSize:10,color:C.textLight,marginBottom:3}}>{a.branch.split(" - ")[0]}</div>
                    <div style={{fontWeight:700,fontSize:14,color:C.text,marginBottom:4}}>{a.house}</div>
                    <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                      <span style={{fontSize:11,background:C.greenPale,color:C.green,borderRadius:6,padding:"1px 7px",fontWeight:600}}>{a.photos.length} ตะกร้า</span>
                      <span style={{fontSize:11,background:C.orangePale,color:C.orange,borderRadius:6,padding:"1px 7px",fontWeight:600}}>{hTotal} ตัว</span>
                    </div>
                    {/* Mini preview */}
                    {a.photos.length>0 && (
                      <div style={{display:"flex",gap:3,marginTop:6}}>
                        {a.photos.slice(0,3).map((p,i)=>(
                          <img key={i} src={p.url} style={{width:38,height:38,objectFit:"cover",borderRadius:6,flex:"0 0 38px"}} alt=""/>
                        ))}
                        {a.photos.length>3 && <div style={{width:38,height:38,borderRadius:6,background:C.grayPale,display:"flex",alignItems:"center",justifyContent:"center",fontSize:11,color:C.textLight,fontWeight:700}}>+{a.photos.length-3}</div>}
                      </div>
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        );
      })}

      <button onClick={()=>setShowNewAlbum(!showNewAlbum)} style={{width:"100%",padding:"13px",borderRadius:12,border:`2px dashed ${C.orange}`,background:C.orangePale,color:C.orange,fontSize:14,fontWeight:700,cursor:"pointer",marginTop:8}}>
        + อัลบั้มใหม่
      </button>
    </div>
  );
}


function AIPage() {
  const [phase, setPhase]       = useState("idle");
  const [imgSrc, setImgSrc]     = useState(null);
  const [result, setResult]     = useState(null);
  const [dots, setDots]         = useState([]);   // [{id,cx,cy,num}] - manual editable
  const [editMode, setEditMode] = useState(false);
  const [eraserMode, setEraserMode] = useState(false);
  const [textMode, setTextMode]   = useState(false);
  const [textLabels, setTextLabels] = useState([]); // [{id,cx,cy,text}]
  const [editingLabel, setEditingLabel] = useState(null); // id being edited
  const [selDot, setSelDot]     = useState(null);
  const [history, setHistory]   = useState([]);
  const [albums, setAlbums]     = useState(INIT_ALBUMS);
  const [selAlbum, setSelAlbum] = useState(null);
  const [tab, setTab]           = useState("camera");
  const [newAlbumName, setNewAlbumName] = useState("");
  const [showNewAlbum, setShowNewAlbum] = useState(false);
  const [watermark, setWatermark] = useState({line1:"จันทร์คำฟาร์ม",line2:"",show:true});
  const [showWMEdit, setShowWMEdit] = useState(false);
  const [imgDims, setImgDims]   = useState({w:1,h:1}); // actual rendered img size
  const imgContRef = { current: null };

  // ── Call Claude API ──
  const handleFile = async (e) => {
    const file = e.target.files[0]; if(!file) return;
    const reader = new FileReader();
    reader.onload = async (ev) => {
      const dataUrl = ev.target.result;
      setImgSrc(dataUrl);
      setDots([]);
      setPhase("counting");
      const now = new Date();
      const dtStr = `${now.getDate().toString().padStart(2,"0")}/${(now.getMonth()+1).toString().padStart(2,"0")}/${now.getFullYear()} ${now.getHours().toString().padStart(2,"0")}:${now.getMinutes().toString().padStart(2,"0")}:${now.getSeconds().toString().padStart(2,"0")}`;
      try {
        const res = await fetch("https://api.anthropic.com/v1/messages",{
          method:"POST", headers:{"Content-Type":"application/json"},
          body: JSON.stringify({
            model:"claude-sonnet-4-20250514", max_tokens:2000,
            messages:[{role:"user",content:[
              {type:"image",source:{type:"base64",media_type:file.type,data:dataUrl.split(",")[1]}},
              {type:"text",text:`You are a precise chick counter. Look at this tray of chicks.

RULES:
- Only mark chicks you are CERTAIN about (clear head or body visible)
- Do NOT mark empty floor, tray edges, shadows, or unclear areas
- Each point must be on a real chick body/head center
- Typical tray: 70-120 chicks

Return ONLY JSON:
{
  "count": <integer>,
  "confidence": "high"|"medium"|"low",
  "note": "<Thai 10 chars>",
  "boxes": [{"cx":<0.0-1.0>,"cy":<0.0-1.0>}]
}
boxes.length must equal count. cx/cy = relative position from top-left corner. Only certain chicks.`}
            ]}]
          })
        });
        const data = await res.json();
        const txt = data.content?.map(i=>i.text||"").join("").replace(/```json|```/g,"").trim();
        const parsed = JSON.parse(txt);
        const newDots = parsed.boxes.map((b,i)=>({id:Date.now()+i, cx:b.cx, cy:b.cy, num:i+1}));
        setResult({...parsed, datetime:dtStr});
        setDots(newDots);
        setPhase("done");
      } catch {
        const mock = Array.from({length:72},(_,i)=>({
          id:i+1, cx:0.08+Math.random()*0.84, cy:0.08+Math.random()*0.84, num:i+1
        }));
        setResult({count:72,confidence:"medium",note:"ตัวอย่าง",datetime:dtStr});
        setDots(mock);
        setPhase("done");
      }
    };
    reader.readAsDataURL(file);
  };

  // ── Tap on image to add dot ──
  const handleImgTap = (e) => {
    if(textMode) { addTextLabel(e); return; }
    if(!editMode && !eraserMode) return;
    if(eraserMode) return; // eraser works via dot click only
    const rect = e.currentTarget.getBoundingClientRect();
    const cx = (e.clientX - rect.left) / rect.width;
    const cy = (e.clientY - rect.top)  / rect.height;
    const newNum = dots.length > 0 ? Math.max(...dots.map(d=>d.num)) + 1 : 1;
    const newDot = {id:Date.now(), cx, cy, num:newNum};
    setHistory(h=>[...h, dots]);
    const updated = [...dots, newDot];
    setDots(updated);
    setResult(r=>({...r, count:updated.length}));
  };

  const handleDotTap = (e, id) => {
    e.stopPropagation();
    e.preventDefault();
    if(eraserMode) {
      deleteDot(id);
    } else if(editMode) {
      setSelDot(selDot===id ? null : id);
    }
  };

  const addTextLabel = (e) => {
    if(!textMode) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const cx = (e.clientX - rect.left) / rect.width;
    const cy = (e.clientY - rect.top)  / rect.height;
    const newLabel = {id:Date.now(), cx, cy, text:"ข้อความ"};
    setTextLabels(prev=>[...prev, newLabel]);
    setEditingLabel(newLabel.id);
  };

  const deleteDot = (id) => {
    setHistory(h=>[...h, dots]);
    const updated = dots.filter(d=>d.id!==id).map((d,i)=>({...d,num:i+1}));
    setDots(updated);
    setResult(r=>({...r,count:updated.length}));
    setSelDot(null);
  };

  const undoLast = () => {
    if(history.length===0) return;
    const prev = history[history.length-1];
    setDots(prev);
    setResult(r=>({...r,count:prev.length}));
    setHistory(h=>h.slice(0,-1));
    setSelDot(null);
  };

  const clearAllDots = () => {
    setHistory(h=>[...h, dots]);
    setDots([]);
    setResult(r=>({...r,count:0}));
    setSelDot(null);
  };

  // ── Save with canvas render ──
  const renderCanvas = () => {
    return new Promise(resolve => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement("canvas");
        const W = img.naturalWidth; const H = img.naturalHeight;
        canvas.width=W; canvas.height=H;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img,0,0,W,H);

        // Draw dots
        const dotR = Math.min(W,H)*0.016;
        const fs   = Math.max(8, dotR*1.1);
        dots.forEach(d=>{
          const x=d.cx*W; const y=d.cy*H;
          // Circle fill
          ctx.beginPath(); ctx.arc(x,y,dotR,0,Math.PI*2);
          ctx.fillStyle="rgba(220,20,20,0.92)"; ctx.fill();
          ctx.strokeStyle="#fff"; ctx.lineWidth=Math.max(1.5,dotR*0.22); ctx.stroke();
          // Number
          ctx.font=`bold ${fs}px sans-serif`;
          ctx.textAlign="center"; ctx.textBaseline="middle";
          ctx.shadowColor="rgba(0,0,0,0.8)"; ctx.shadowBlur=2;
          ctx.fillStyle="#fff";
          ctx.fillText(d.num,x,y);
          ctx.shadowBlur=0;
        });

        // Text labels
        if(textLabels.length > 0) {
          textLabels.forEach(lbl => {
            const lx = lbl.cx * W;
            const ly = lbl.cy * H;
            const lfs = Math.max(14, W*0.022);
            ctx.font = `bold ${lfs}px sans-serif`;
            const tw = ctx.measureText(lbl.text).width;
            // background pill
            ctx.fillStyle = "rgba(0,0,0,0.6)";
            const pad = lfs*0.3;
            ctx.beginPath();
            ctx.roundRect(lx-pad, ly-lfs*0.65, tw+pad*2, lfs*1.3, lfs*0.3);
            ctx.fill();
            // text
            ctx.fillStyle = "#FFE000";
            ctx.textAlign = "left";
            ctx.textBaseline = "middle";
            ctx.fillText(lbl.text, lx, ly);
          });
        }

        // Watermark
        if(watermark.show && result) {
          const lines=[result.datetime||"",watermark.line1,watermark.line2,`นับได้ ${dots.length} ตัว`].filter(Boolean);
          const wfs=Math.max(14,W*0.025);
          ctx.font=`bold ${wfs}px sans-serif`; ctx.textAlign="right"; ctx.textBaseline="top";
          lines.forEach((line,i)=>{
            const y2=12+i*(wfs+4);
            ctx.fillStyle="rgba(0,0,0,0.6)"; ctx.fillText(line,W-9,y2+2);
            ctx.fillStyle="#fff"; ctx.fillText(line,W-10,y2);
          });
        }
        resolve(canvas.toDataURL("image/jpeg",0.88));
      };
      img.src = imgSrc;
    });
  };

  const saveToAlbum = async (albumId) => {
    const url = await renderCanvas();
    setAlbums(prev=>prev.map(a=>{
      if(a.id!==albumId) return a;
      const basket = a.photos.length + 1;
      return {...a, photos:[...a.photos, {url, count:dots.length, date:today(), basket}]};
    }));
    alert(`บันทึกตะกร้าที่ ${(albums.find(a=>a.id===albumId)?.photos.length||0)+1} แล้ว ✓`);
  };

  const downloadImg = async () => {
    const url = await renderCanvas();
    const a = document.createElement("a");
    a.href=url; a.download=`chick-count-${today()}.jpg`; a.click();
  };

  return (
    <div style={{fontFamily:"'Sarabun',sans-serif"}}>
      {/* Tabs */}
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:14}}>
        {[["camera","📷 นับไก่ AI"],["albums","📁 อัลบั้ม"]].map(([v,l])=>(
          <button key={v} onClick={()=>setTab(v)} style={{
            padding:"9px",borderRadius:10,border:"1.5px solid",fontSize:13,fontWeight:600,cursor:"pointer",
            borderColor:tab===v?C.orange:C.greenMid,background:tab===v?C.orange:C.white,color:tab===v?C.white:C.textMid,
          }}>{l}</button>
        ))}
      </div>

      {tab==="camera" && (
        <div>
          {/* Watermark bar */}
          <div style={{background:C.yellow,borderRadius:12,padding:"8px 14px",marginBottom:10,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
            <div>
              <div style={{fontSize:11,color:C.textLight}}>🕐 timestamp อัตโนมัติ + ชื่อฟาร์ม</div>
              <div style={{fontSize:12,color:C.ink}}>{watermark.line1}{watermark.line2?" · "+watermark.line2:""}</div>
            </div>
            <button onClick={()=>setShowWMEdit(!showWMEdit)} style={{padding:"4px 10px",borderRadius:8,border:`1px solid ${C.yellowD}`,background:C.white,color:C.ink,fontSize:11,cursor:"pointer"}}>✏️ แก้ไข</button>
          </div>
          {showWMEdit && (
            <Card style={{marginBottom:10}}>
              <label style={LS}>บรรทัด 1</label>
              <input value={watermark.line1} onChange={e=>setWatermark(w=>({...w,line1:e.target.value}))} style={{...IS,marginBottom:8}}/>
              <label style={LS}>บรรทัด 2</label>
              <input value={watermark.line2} onChange={e=>setWatermark(w=>({...w,line2:e.target.value}))} placeholder="เช่น รุ่น 1/68 เล้า H4" style={{...IS,marginBottom:8}}/>
              <div style={{display:"flex",gap:8,alignItems:"center"}}>
                <label style={{fontSize:13,display:"flex",alignItems:"center",gap:6}}>
                  <input type="checkbox" checked={watermark.show} onChange={e=>setWatermark(w=>({...w,show:e.target.checked}))}/>
                  แสดง watermark
                </label>
                <button onClick={()=>setShowWMEdit(false)} style={{marginLeft:"auto",padding:"5px 12px",borderRadius:8,border:"none",background:C.green,color:C.white,fontSize:12,fontWeight:700,cursor:"pointer"}}>✓</button>
              </div>
            </Card>
          )}

          {/* IDLE */}
          {phase==="idle" && (
            <div>
              <div style={{background:`linear-gradient(135deg,${C.orange},#E8A020)`,borderRadius:18,padding:"28px 20px",color:C.white,textAlign:"center",marginBottom:14}}>
                <div style={{fontSize:52,marginBottom:8}}>🐥</div>
                <div style={{fontFamily:"serif",fontSize:20,fontWeight:700,marginBottom:4}}>AI นับลูกไก่</div>
                <div style={{fontSize:13,opacity:0.85}}>นับเฉพาะที่ชัวร์ · แก้ไขจุดได้</div>
              </div>
              <label style={{display:"block",width:"100%",padding:"16px",borderRadius:14,border:"none",background:C.orange,color:C.white,fontSize:16,fontWeight:700,cursor:"pointer",textAlign:"center",marginBottom:10,boxSizing:"border-box"}}>
                <input type="file" accept="image/*" capture="environment" onChange={handleFile} style={{display:"none"}}/>📷 ถ่ายรูปนับไก่
              </label>
              <label style={{display:"block",width:"100%",padding:"16px",borderRadius:14,border:`2px dashed ${C.orange}`,background:C.orangePale,color:C.orange,fontSize:16,fontWeight:700,cursor:"pointer",textAlign:"center",boxSizing:"border-box"}}>
                <input type="file" accept="image/*" onChange={handleFile} style={{display:"none"}}/>🖼️ เลือกจากคลัง
              </label>
            </div>
          )}

          {/* COUNTING */}
          {phase==="counting" && (
            <div style={{textAlign:"center",padding:"48px 20px"}}>
              {imgSrc&&<img src={imgSrc} style={{width:"100%",borderRadius:14,marginBottom:16,maxHeight:220,objectFit:"cover"}} alt=""/>}
              <div style={{fontSize:52}}>🔍</div>
              <div style={{fontWeight:700,fontSize:20,color:C.orange,fontFamily:"serif",marginTop:8}}>กำลังนับ...</div>
              <div style={{fontSize:13,color:C.textMid,marginTop:4}}>นับเฉพาะที่ชัวร์ว่าเป็นไก่</div>
            </div>
          )}

          {/* DONE */}
          {phase==="done" && result && (
            <div>
              {/* Count + confidence */}
              <div style={{background:`linear-gradient(135deg,${C.green},${C.greenL})`,borderRadius:14,padding:"14px 18px",color:C.white,textAlign:"center",marginBottom:10,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                <div>
                  <div style={{fontSize:11,opacity:0.8}}>นับได้ (ชัวร์)</div>
                  <div style={{fontSize:40,fontWeight:700,fontFamily:"serif",lineHeight:1}}>{dots.length}</div>
                  <div style={{fontSize:12,opacity:0.8}}>ตัว</div>
                </div>
                <div style={{textAlign:"right"}}>
                  <div style={{fontSize:11,opacity:0.8}}>ความมั่นใจ</div>
                  <div style={{fontSize:14,fontWeight:700}}>{result.confidence==="high"?"สูง ✓":result.confidence==="medium"?"ปานกลาง":"ต่ำ"}</div>
                  <div style={{fontSize:11,opacity:0.8,marginTop:4}}>{result.note}</div>
                </div>
              </div>

              {/* Toolbar: edit + eraser + undo + clear */}
              <div style={{display:"flex",gap:6,marginBottom:10,flexWrap:"wrap"}}>
                <button onClick={()=>{setEditMode(!editMode);setEraserMode(false);setTextMode(false);setSelDot(null);}} style={{
                  flex:1,padding:"9px 6px",borderRadius:10,border:"1.5px solid",fontSize:12,fontWeight:700,cursor:"pointer",
                  borderColor:editMode?C.blue:C.greenMid,
                  background:editMode?C.blue:C.white,
                  color:editMode?C.white:C.textMid,
                }}>✏️ เพิ่มจุด</button>

                <button onClick={()=>{setEraserMode(!eraserMode);setEditMode(false);setTextMode(false);setSelDot(null);}} style={{
                  flex:1,padding:"9px 6px",borderRadius:10,border:"1.5px solid",fontSize:12,fontWeight:700,cursor:"pointer",
                  borderColor:eraserMode?C.orange:C.greenMid,
                  background:eraserMode?C.orange:C.white,
                  color:eraserMode?C.white:C.textMid,
                }}>🧹 {eraserMode?"ยางลบ ON":"ยางลบ"}</button>

                <button onClick={()=>{setTextMode(!textMode);setEditMode(false);setEraserMode(false);setSelDot(null);}} style={{
                  padding:"9px 6px",borderRadius:10,border:"1.5px solid",fontSize:12,fontWeight:700,cursor:"pointer",
                  borderColor:textMode?C.purple:C.greenMid,
                  background:textMode?C.purple:C.white,
                  color:textMode?C.white:C.textMid,
                }}>🔤 ข้อความ</button>

                <button onClick={undoLast} disabled={history.length===0} style={{
                  padding:"9px 12px",borderRadius:10,border:`1.5px solid ${C.greenMid}`,
                  background:history.length>0?C.yellow:C.grayPale,
                  color:history.length>0?C.ink:C.textLight,
                  fontSize:12,fontWeight:600,cursor:history.length>0?"pointer":"not-allowed"
                }}>↩️ ย้อน</button>

                <button onClick={()=>{if(dots.length===0)return;clearAllDots();}} style={{
                  padding:"9px 12px",borderRadius:10,border:`1.5px solid ${C.red}`,
                  background:C.redPale,color:C.red,
                  fontSize:12,fontWeight:600,cursor:"pointer"
                }}>🗑️ ล้าง</button>
              </div>

              {/* Mode hint */}
              {(editMode||eraserMode||textMode||selDot) && (
                <div style={{background:textMode?C.purplePale:eraserMode?C.orangePale:C.bluePale,borderRadius:10,padding:"7px 12px",marginBottom:10,fontSize:12,color:textMode?C.purple:eraserMode?C.orange:C.blue,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                  {textMode && <span>🔤 แตะบนรูปเพื่อวางข้อความ</span>}
                  {eraserMode && !textMode && <span>🧹 แตะจุดแดงเพื่อลบทันที</span>}
                  {editMode && !eraserMode && !textMode && <span>✏️ แตะบนรูปเพื่อเพิ่มจุด</span>}
                  {selDot && !eraserMode && !textMode && (
                    <button onClick={()=>deleteDot(selDot)} style={{padding:"4px 10px",borderRadius:7,border:"none",background:C.red,color:C.white,fontSize:11,fontWeight:700,cursor:"pointer"}}>
                      ลบ #{dots.find(d=>d.id===selDot)?.num}
                    </button>
                  )}
                </div>
              )}

              {/* Image with interactive dots */}
              <div style={{position:"relative",borderRadius:14,overflow:"hidden",marginBottom:10,border:`1.5px solid ${C.greenMid}`,cursor:editMode?"crosshair":"default"}}
                   onClick={handleImgTap}>
                <img src={imgSrc} style={{width:"100%",display:"block"}} alt=""
                     onLoad={e=>setImgDims({w:e.target.offsetWidth,h:e.target.offsetHeight})}/>
                {/* SVG overlay for dots */}
                <svg style={{position:"absolute",inset:0,width:"100%",height:"100%",pointerEvents:"none"}} viewBox="0 0 100 100" preserveAspectRatio="none">
                  {dots.map(d=>{
                    const isSel = selDot===d.id;
                    return (
                      <g key={d.id}
                         style={{cursor:eraserMode?"cell":editMode?"pointer":"default", pointerEvents:"all"}}
                         onClick={e=>handleDotTap(e,d.id)}>
                        {/* Larger invisible hit area */}
                        <circle cx={d.cx*100} cy={d.cy*100} r="3" fill="transparent"/>
                        <circle cx={d.cx*100} cy={d.cy*100} r="1.6"
                          fill={isSel?"rgba(255,200,0,0.95)":eraserMode?"rgba(255,80,20,0.95)":"rgba(210,20,20,0.92)"}
                          stroke="white" strokeWidth="0.4"/>
                        <text x={d.cx*100} y={d.cy*100+0.55} textAnchor="middle"
                          fontSize="1.1" fontWeight="bold" fill="white"
                          fontFamily="sans-serif" style={{pointerEvents:"none"}}>{d.num}</text>
                      </g>
                    );
                  })}
                </svg>
                {/* Text labels on SVG */}
                {textLabels.map(lbl=>(
                  <g key={lbl.id} onClick={e=>{e.stopPropagation();setEditingLabel(lbl.id);}}>
                    <rect x={lbl.cx*100-1} y={lbl.cy*100-2.2} width={Math.min(lbl.text.length*1.8+2,35)} height="4.5"
                      fill="rgba(0,0,0,0.6)" rx="0.8"/>
                    <text x={lbl.cx*100} y={lbl.cy*100+0.3} fontSize="2.8" fontWeight="bold"
                      fill="#FFE000" fontFamily="sans-serif">{lbl.text}</text>
                  </g>
                ))}
                <div style={{position:"absolute",bottom:6,left:6,background:"rgba(0,0,0,0.6)",borderRadius:7,padding:"2px 8px",fontSize:11,color:C.white}}>
                  🔴 = 1 ตัว · รวม {dots.length} ตัว
                </div>
              </div>

              {/* Inline text editor */}
              {editingLabel && (()=>{
                const lbl = textLabels.find(l=>l.id===editingLabel);
                if(!lbl) return null;
                return (
                  <div style={{background:C.purplePale,border:`1.5px solid ${C.purple}`,borderRadius:12,padding:"12px 14px",marginBottom:10,display:"flex",gap:8,alignItems:"center"}}>
                    <span style={{fontSize:13,color:C.purple,fontWeight:600,flexShrink:0}}>🔤 แก้ข้อความ:</span>
                    <input autoFocus value={lbl.text}
                      onChange={e=>setTextLabels(prev=>prev.map(l=>l.id===editingLabel?{...l,text:e.target.value}:l))}
                      style={{...IS,flex:1,padding:"7px 10px",fontSize:13}}/>
                    <button onClick={()=>setTextLabels(prev=>prev.filter(l=>l.id!==editingLabel))||setEditingLabel(null)}
                      style={{padding:"7px 10px",borderRadius:8,border:"none",background:C.red,color:C.white,fontSize:12,fontWeight:700,cursor:"pointer"}}>ลบ</button>
                    <button onClick={()=>setEditingLabel(null)}
                      style={{padding:"7px 10px",borderRadius:8,border:"none",background:C.purple,color:C.white,fontSize:12,fontWeight:700,cursor:"pointer"}}>✓</button>
                  </div>
                );
              })()}

              {/* Save to album */}
              <Card style={{marginBottom:10}}>
                <div style={{fontWeight:700,fontSize:13,color:C.text,marginBottom:8}}>💾 บันทึกลงอัลบั้ม</div>
                <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:showNewAlbum?8:0}}>
                  {albums.map(a=>(
                    <button key={a.id} onClick={()=>saveToAlbum(a.id)} style={{
                      padding:"6px 12px",borderRadius:9,border:`1.5px solid ${C.orange}`,
                      background:C.orangePale,color:C.orange,fontSize:12,fontWeight:600,cursor:"pointer"
                    }}>{a.batchName||a.name} · {a.house}</button>
                  ))}
                  <button onClick={()=>setShowNewAlbum(!showNewAlbum)} style={{padding:"6px 12px",borderRadius:9,border:`1.5px dashed ${C.greenMid}`,background:C.white,color:C.textMid,fontSize:12,cursor:"pointer"}}>+ อัลบั้มใหม่</button>
                </div>
                {showNewAlbum&&(
                  <div style={{display:"flex",gap:6}}>
                    <input value={newAlbumName} onChange={e=>setNewAlbumName(e.target.value)} placeholder="เช่น รุ่น 1/68 เล้า H4" style={{...IS,flex:1}}/>
                    <button onClick={()=>{if(!newAlbumName)return;setAlbums(prev=>[...prev,{id:Date.now(),name:newAlbumName,date:today(),photos:[]}]);setNewAlbumName("");setShowNewAlbum(false);}} style={{padding:"10px 14px",borderRadius:10,border:"none",background:C.green,color:C.white,fontWeight:700,cursor:"pointer"}}>✓</button>
                  </div>
                )}
              </Card>

              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
                <button onClick={downloadImg} style={{padding:"12px",borderRadius:12,border:`1.5px solid ${C.blue}`,background:C.bluePale,color:C.blue,fontSize:13,fontWeight:600,cursor:"pointer"}}>⬇️ ดาวน์โหลด</button>
                <button onClick={()=>{setPhase("idle");setImgSrc(null);setResult(null);setDots([]);setEditMode(false);}} style={{padding:"12px",borderRadius:12,border:"none",background:C.orange,color:C.white,fontSize:13,fontWeight:700,cursor:"pointer"}}>📷 ถ่ายใหม่</button>
              </div>
            </div>
          )}
        </div>
      )}

      {/* ALBUMS TAB */}
      {tab==="albums" && (
        <AlbumBrowser
          albums={albums} setAlbums={setAlbums}
          showNewAlbum={showNewAlbum} setShowNewAlbum={setShowNewAlbum}
          newAlbumName={newAlbumName} setNewAlbumName={setNewAlbumName}
        />
      )}
    </div>
  );
}

